/* CSIR NET Life Sciences, June 2024 (exam of 26 July 2024, shift 1): 145 questions.
 * Scored against the answer key published for this paper (challenge window), which may differ from
 * NTA's final key on a few questions. Loaded on demand by index.html when a candidate opens the paper.
 * Each question: id (1-145), part (A/B/C), unit (syllabus unit 1-14, null for Part A), blocks (text / image / table),
 * options (keys 1-4), answer (the key of the correct option) and explanation ({correct, wrong, notes}). */
window.PYQ_PAPERS = window.PYQ_PAPERS || {};
window.PYQ_PAPERS['pyq-jun2024'] = [{"id":1,"part":"A","unit":null,"blocks":[{"t":"p","h":"In humans, if both parents are of blood group AB, then, there is a 1/4 probability that their offspring will be of blood group A, and 1/2 probability that the offspring will be of blood group AB. If the couple have three children, what is the probability that NONE of the children will be of blood group A or AB?"}],"options":[{"key":"1","text":"1/4"},{"key":"2","text":"3/4"},{"key":"3","text":"1/64"},{"key":"4","text":"63/64"}],"answer":"3","explanation":{"correct":"For an AB × AB cross the offspring are A (1/4), AB (1/2) and B (1/4). A child who is neither A nor AB must be B, with probability 1/4. The three births are independent, so the probability that all three are B is (1/4)³ = <b>1/64</b>.","wrong":{"1":"1/4 is the probability for one child only, not for all three.","2":"3/4 is the probability that a single child <i>is</i> A or AB.","4":"63/64 = 1 − 1/64 is the probability that <i>at least one</i> child is A or AB."}}},{"id":2,"part":"A","unit":null,"blocks":[{"t":"p","h":"Every element in the central column of the matrix has a simple arithmetic relationship with the pairs on the left and right in the corresponding row."},{"t":"tbl","cls":"","rowHead":false,"head":[],"rows":[["17","12","<b>1</b>","19","23"],["23","21","<b><i>X</i></b>","18","20"],["24","17","<b>3</b>","32","36"],["35","28","<b>2</b>","19","24"]]},{"t":"p","h":"What would be the value of <i>X</i>?"}],"options":[{"key":"1","text":"2"},{"key":"2","text":"1"},{"key":"3","text":"0"},{"key":"4","text":"−1"}],"answer":"3","explanation":{"correct":"Centre = (difference of the left pair) − (difference of the right pair). Row 1: (17 − 12) − (23 − 19) = 5 − 4 = 1. Row 3: (24 − 17) − (36 − 32) = 7 − 4 = 3. Row 4: (35 − 28) − (24 − 19) = 7 − 5 = 2. Row 2: (23 − 21) − (20 − 18) = 2 − 2 = <b>0</b>.","wrong":{"1":"2 is the left-pair (or right-pair) difference of row 2 alone, not the difference between them.","2":"1 does not fit the rule that works for the other three rows.","4":"−1 would need the right-pair difference to exceed the left-pair difference by 1."}}},{"id":3,"part":"A","unit":null,"blocks":[{"t":"p","h":"For any four consecutive decimal digits, the largest value of the product of the sum of any two and the sum of the other two is"}],"options":[{"key":"1","text":"an even number and a perfect square"},{"key":"2","text":"an even number, but not a perfect square"},{"key":"3","text":"an odd number and a perfect square"},{"key":"4","text":"an odd number, but not a perfect square"}],"answer":"3","explanation":{"correct":"Let the digits be <i>n</i>, <i>n</i>+1, <i>n</i>+2, <i>n</i>+3 (total 4<i>n</i>+6). For a fixed total, a product of two parts is largest when the parts are as equal as possible. Pairing the outer and inner digits gives two equal sums of 2<i>n</i>+3. The other pairings give (2<i>n</i>+1)(2<i>n</i>+5) = (2<i>n</i>+3)² − 4 or (2<i>n</i>+2)(2<i>n</i>+4) = (2<i>n</i>+3)² − 1. So the maximum is (2<i>n</i>+3)², the square of an odd number: <b>odd and a perfect square</b>. For example, 3, 4, 5, 6 gives (3+6)(4+5) = 81.","wrong":{"1":"2<i>n</i>+3 is always odd, so its square cannot be even.","2":"The maximum is neither even nor a non-square.","4":"The maximum is always a perfect square, (2<i>n</i>+3)²."}}},{"id":4,"part":"A","unit":null,"blocks":[{"t":"p","h":"A record player stylus moves along a spiral groove cut on an annular portion of a disc. A record with inner radius 4 cm and outer radius 10 cm of the annulus, turning 100 times plays for 22 minutes. During this time the stylus travels at an average linear speed that is approximately equal to"}],"options":[{"key":"1","text":"100 m/h"},{"key":"2","text":"120 m/h"},{"key":"3","text":"220 m/h"},{"key":"4","text":"440 m/h"}],"answer":"2","explanation":{"correct":"The groove's 100 turns run evenly from <i>r</i> = 10 cm to 4 cm, so the mean circumference is 2π × 7 cm ≈ 44 cm. Groove length ≈ 100 × 44 cm = 44 m. Time = 22 min = 22/60 h. Average speed = 44 ÷ (22/60) = <b>120 m/h</b>.","wrong":{"1":"100 m/h would need a groove of only about 37 m.","3":"220 m/h comes from using the outer radius twice over or from mixing up minutes and hours.","4":"440 m/h is about four times the true value (for example, using the diameter instead of the radius twice)."}}},{"id":5,"part":"A","unit":null,"blocks":[{"t":"p","h":"Consider the first few consecutive natural numbers. The ratio of the sum of their squares to their sum can NEVER be"}],"options":[{"key":"1","text":"67"},{"key":"2","text":"75"},{"key":"3","text":"91"},{"key":"4","text":"100"}],"answer":"4","explanation":{"correct":"For the first <i>n</i> natural numbers, Σ<i>k</i>² / Σ<i>k</i> = [<i>n</i>(<i>n</i>+1)(2<i>n</i>+1)/6] ÷ [<i>n</i>(<i>n</i>+1)/2] = (2<i>n</i>+1)/3. Setting (2<i>n</i>+1)/3 = 100 needs 2<i>n</i>+1 = 300, which is impossible because 2<i>n</i>+1 is always odd. So the ratio can never be <b>100</b>.","wrong":{"1":"67 occurs for <i>n</i> = 100 (2<i>n</i>+1 = 201).","2":"75 occurs for <i>n</i> = 112 (2<i>n</i>+1 = 225).","3":"91 occurs for <i>n</i> = 136 (2<i>n</i>+1 = 273)."}}},{"id":6,"part":"A","unit":null,"blocks":[{"t":"p","h":"If 16<i>x</i>² − 25<i>y</i>² + 7 = 0, <i>x</i> and <i>y</i> being positive numbers, then which of the following may hold?"}],"options":[{"key":"1","text":"4<i>x</i> + 5<i>y</i> + 1 = 0"},{"key":"2","text":"4<i>x</i> + 5<i>y</i> + 7 = 0"},{"key":"3","text":"4<i>x</i> − 5<i>y</i> + 1 = 0"},{"key":"4","text":"4<i>x</i> − 5<i>y</i> − 7 = 0"}],"answer":"3","explanation":{"correct":"Factorise: (4<i>x</i> − 5<i>y</i>)(4<i>x</i> + 5<i>y</i>) = −7. With <i>x</i>, <i>y</i> &gt; 0, 4<i>x</i> + 5<i>y</i> is positive, so 4<i>x</i> − 5<i>y</i> must be negative. Try 4<i>x</i> − 5<i>y</i> = −1: then 4<i>x</i> + 5<i>y</i> = 7, giving <i>x</i> = 0.75 and <i>y</i> = 0.8, both positive. So <b>4<i>x</i> − 5<i>y</i> + 1 = 0</b> can hold.","wrong":{"1":"4<i>x</i> + 5<i>y</i> = −1 is impossible for positive <i>x</i> and <i>y</i>.","2":"4<i>x</i> + 5<i>y</i> = −7 is impossible for positive <i>x</i> and <i>y</i>.","4":"4<i>x</i> − 5<i>y</i> = 7 would force 4<i>x</i> + 5<i>y</i> = −1, which is impossible."}}},{"id":7,"part":"A","unit":null,"blocks":[{"t":"p","h":"Among five girls standing side by side, Leela has exactly one girl to her left, Alice is just right of Prerna, and there are at least two girls between Radha and Zarina. The girl in the middle is"}],"options":[{"key":"1","text":"Prerna"},{"key":"2","text":"Alice"},{"key":"3","text":"Leela"},{"key":"4","text":"Zarina"}],"answer":"1","explanation":{"correct":"Leela is in position 2. Radha and Zarina need at least two girls between them and cannot use position 2, so they take positions 1 and 4 or 1 and 5. With 1 and 4, the free places 3 and 5 are not adjacent, so Prerna–Alice cannot fit. So Radha/Zarina are at 1 and 5, and Prerna and Alice fill 3 and 4 in that order. The middle girl (position 3) is <b>Prerna</b>.","wrong":{"2":"Alice must be immediately right of Prerna, so she is in position 4.","3":"Leela has exactly one girl to her left, so she is in position 2.","4":"Zarina is at an end (position 1 or 5)."}}},{"id":8,"part":"A","unit":null,"blocks":[{"t":"p","h":"Suppose liars always lie and truthful persons never. In a group of 4 people A, B, C and D, A says, \"We're all liars\", B says, \"Only one of us is a liar\", C says, \"No, exactly two of us are liars\" and D says, \"I'm truthful\". Which among the following is definitely FALSE?"}],"options":[{"key":"1","text":"A is a liar"},{"key":"2","text":"B is a liar"},{"key":"3","text":"C is a liar"},{"key":"4","text":"D is a liar"}],"answer":"4","explanation":{"correct":"If A were truthful, \"we're all liars\" would make A a liar, a contradiction. So A is a liar, and not everyone is a liar. If B were truthful, A would be the only liar, so C's claim of two liars would be false and C would be a second liar, a contradiction. So B is also a liar. That leaves two consistent cases: C truthful and D truthful (exactly two liars), or C a liar and D truthful (three liars; D cannot also lie, or all four would be liars, which A's lie rules out). In every case D is truthful, so \"<b>D is a liar</b>\" is definitely false.","wrong":{"1":"A is necessarily a liar, so this statement is true.","2":"B is necessarily a liar, so this statement is true.","3":"C may be a liar (the three-liar case), so this is not <i>definitely</i> false."}}},{"id":9,"part":"A","unit":null,"blocks":[{"t":"p","h":"The growth model for a population is <i>N<sub>t</sub></i> = <i>N</i><sub>0</sub><i>e<sup>rt</sup></i>, where <i>N<sub>t</sub></i> is the population at time <i>t</i>, <i>N</i><sub>0</sub> is the initial population and <i>r</i> is the per capita growth rate. How long does it take for the population numbers to double?"}],"options":[{"key":"1","text":"(ln 2)/<i>r</i>"},{"key":"2","text":"2/<i>r</i>"},{"key":"3","text":"1/(<i>r</i> ln 2)"},{"key":"4","text":"1/<i>r</i>"}],"answer":"1","explanation":{"correct":"Doubling means 2<i>N</i><sub>0</sub> = <i>N</i><sub>0</sub><i>e<sup>rt</sup></i>, so <i>e<sup>rt</sup></i> = 2 and <i>t</i> = <b>(ln 2)/<i>r</i></b> ≈ 0.693/<i>r</i>. This is the familiar doubling time of exponential growth.","wrong":{"2":"2/<i>r</i> confuses the factor 2 with ln 2.","3":"1/(<i>r</i> ln 2) inverts ln 2.","4":"1/<i>r</i> is the time to grow by a factor of <i>e</i>, not 2."}}},{"id":10,"part":"A","unit":null,"blocks":[{"t":"p","h":"A straight irrigation canal in a plain area has a floor at a depth of 5 m from the surface. The canal is 20 m wide at the surface. The floor of the canal is flat and the embankments have a slope of 45°. When it is completely filled, what will be the volume of water (in m³) in the canal over a length of 100 m?"}],"options":[{"key":"1","text":"6000"},{"key":"2","text":"7500"},{"key":"3","text":"8000"},{"key":"4","text":"9500"}],"answer":"2","explanation":{"correct":"The cross-section is a trapezium. With 45° banks, each side moves in 5 m horizontally over a 5 m depth, so the floor is 20 − 2 × 5 = 10 m wide. Area = ½(20 + 10) × 5 = 75 m². Volume over 100 m = <b>7500 m³</b>.","wrong":{"1":"6000 m³ does not correspond to any consistent trapezium width.","3":"8000 m³ does not fit the dimensions given.","4":"9500 m³ is close to the 10,000 m³ of a rectangular 20 m × 5 m channel, so it largely ignores the sloping banks."}}},{"id":11,"part":"A","unit":null,"blocks":[{"t":"p","h":"If <i>X</i> &gt; <i>Y</i> &gt; 0, then <i>X</i>% of <i>Y</i> is"}],"options":[{"key":"1","text":"equal to <i>Y</i>% of <i>X</i>"},{"key":"2","text":"more than <i>Y</i>% of <i>X</i>"},{"key":"3","text":"less than <i>Y</i>% of <i>X</i>"},{"key":"4","text":"(<i>X</i> + <i>Y</i>)% of (<i>X</i> + <i>Y</i>)"}],"answer":"1","explanation":{"correct":"<i>X</i>% of <i>Y</i> = <i>XY</i>/100 = <i>Y</i>% of <i>X</i>. Multiplication is commutative, so the two are <b>always equal</b> whatever the sizes of <i>X</i> and <i>Y</i>.","wrong":{"2":"The two quantities are identical, so neither is larger.","3":"The two quantities are identical, so neither is smaller.","4":"(<i>X</i>+<i>Y</i>)²/100 is larger than <i>XY</i>/100 for all positive <i>X</i>, <i>Y</i>."}}},{"id":12,"part":"A","unit":null,"blocks":[{"t":"p","h":"A certain item of raw food contains 35% starch, 25% protein, the rest fibre. The item is cooked by boiling in water, which doubles its weight. Half of the fibre in the food becomes soluble when cooked. If the cooked item weighs 200 g, the amount of soluble fibre in it is"}],"options":[{"key":"1","text":"15 g"},{"key":"2","text":"30 g"},{"key":"3","text":"20 g"},{"key":"4","text":"40 g"}],"answer":"3","explanation":{"correct":"The cooked item weighs 200 g, so the raw item weighed 100 g (cooking doubles the weight by adding water). Fibre = 100 − 35 − 25 = 40% of 100 g = 40 g. Half becomes soluble: <b>20 g</b>.","wrong":{"1":"15 g has no basis in the given percentages.","2":"30 g would need 60 g of fibre.","4":"40 g is the total fibre, not the soluble half."}}},{"id":13,"part":"A","unit":null,"blocks":[{"t":"p","h":"A ball starts rolling from the edge of the slope at time <i>t</i> = 0 as shown in the diagram."},{"t":"img","src":"data:image/webp;base64,","w":274,"h":136,"alt":"A curved bowl-shaped slope from position −2 to +2 with a ball at the rim at +2"},{"t":"p","h":"Referring to the graphs A, B, C, which of the following statements is correct?"},{"t":"img","src":"data:image/webp;base64,","w":767,"h":235,"alt":"Three position–time graphs. A: oscillation that starts at +2 and decays in amplitude. B: oscillation that starts near 0 and decays. C: oscillation between +2 and −2 with constant amplitude"}],"options":[{"key":"1","text":"A depicts motion with friction while C depicts motion without friction"},{"key":"2","text":"C depicts motion with friction while A depicts motion without friction"},{"key":"3","text":"B depicts motion with friction while A depicts motion without friction"},{"key":"4","text":"B depicts motion with friction while C depicts motion without friction"}],"answer":"1","explanation":{"correct":"The ball is released from rest at the rim, so at <i>t</i> = 0 its position is +2 (a turning point). Without friction mechanical energy is conserved and it oscillates between +2 and −2 forever (graph <b>C</b>). With friction energy is dissipated, so the amplitude decays while the trace still starts at +2 (graph <b>A</b>). Graph B starts from the bottom of the bowl (position 0), which does not match a release from the edge.","wrong":{"2":"Reversed: C has constant amplitude (no dissipation) and A decays.","3":"B does not start at the release point, and A is damped, so it does not show frictionless motion.","4":"C is right for frictionless motion, but B does not start at the release point +2."}}},{"id":14,"part":"A","unit":null,"blocks":[{"t":"p","h":"The graph shows average run rate (runs scored per over) by teams A and B in a twenty overs cricket match."},{"t":"img","src":"data:image/webp;base64,","w":391,"h":190,"alt":"Bar chart of runs per over in four 5-over blocks. Team A: 9, 12, 10, 14. Team B: 10, 13, 8, 12"},{"t":"p","h":"Select the INCORRECT statement."}],"options":[{"key":"1","text":"Team B scored more runs than team A in the first 10 overs."},{"key":"2","text":"Team A scored more runs than team B in all."},{"key":"3","text":"Team B scored more runs in overs 1—10 than in overs 11—20."},{"key":"4","text":"Team A has a lower overall run rate than team B."}],"answer":"4","explanation":{"correct":"Runs = rate × 5 overs per block. Team A: 45 + 60 + 50 + 70 = 225. Team B: 50 + 65 + 40 + 60 = 215. Team A's overall rate is 225/20 = 11.25 and team B's is 215/20 = 10.75, so A's rate is <i>higher</i>. Statement 4 is therefore the incorrect one.","wrong":{"1":"True: in overs 1–10, B scored 115 and A scored 105.","2":"True: 225 against 215.","3":"True: B scored 115 in overs 1–10 and 100 in overs 11–20."}}},{"id":15,"part":"A","unit":null,"blocks":[{"t":"p","h":"A spherical object of radius 6 cm was melted and cast into a cylindrical bar of radius 3 cm. What would be the length (in cm) of the bar?"}],"options":[{"key":"1","text":"24"},{"key":"2","text":"32"},{"key":"3","text":"36"},{"key":"4","text":"42"}],"answer":"2","explanation":{"correct":"Volume is conserved. (4/3)π(6)³ = 288π cm³ = π(3)²<i>L</i> = 9π<i>L</i>, so <i>L</i> = <b>32 cm</b>.","wrong":{"1":"24 cm leaves out a factor of 4/3.","3":"36 cm would hold 324π cm³, more than the sphere's volume.","4":"42 cm is far more than the volume allows."}}},{"id":16,"part":"A","unit":null,"blocks":[{"t":"p","h":"The total monthly income of a family is split into expenses on food (F), house rent (H), college fees (C), entertainment (E), miscellaneous items (M), and savings (S), as shown in the pie chart."},{"t":"img","src":"data:image/webp;base64,","w":203,"h":153,"alt":"Pie chart: F 20%, H 25%, C 15%, E 10%, M 15%, S 15%"},{"t":"p","h":"The family transfers an amount of Rs 1000/- from the head food to the head entertainment, thereby making the expenses on the two heads equal. What is the net expenditure of the family?"}],"options":[{"key":"1","text":"Rs 20,000"},{"key":"2","text":"Rs 50,000"},{"key":"3","text":"Rs 37,500"},{"key":"4","text":"Rs 17,000"}],"answer":"4","explanation":{"correct":"Food (20%) and entertainment (10%) become equal after Rs 1000 moves from one to the other, so their gap of 10% of income equals Rs 2000. Income = Rs 20,000. Savings are 15%, so the net <i>expenditure</i> is 85% of 20,000 = <b>Rs 17,000</b>.","wrong":{"1":"Rs 20,000 is the total income, which includes savings.","2":"Rs 50,000 would follow from treating Rs 1000 as a 2% gap.","3":"Rs 37,500 has no basis in the chart."}}},{"id":17,"part":"A","unit":null,"blocks":[{"t":"p","h":"A 1 m long rod having diameter of 12 mm weighs 880 g. What, approximately, is the density (in g/cm³) of the material of the rod?"}],"options":[{"key":"1","text":"6.2"},{"key":"2","text":"6.6"},{"key":"3","text":"7.8"},{"key":"4","text":"8.8"}],"answer":"3","explanation":{"correct":"Volume = π<i>r</i>²<i>L</i> = π(0.6 cm)²(100 cm) ≈ 113.1 cm³. Density = 880 / 113.1 ≈ <b>7.8 g/cm³</b>, about the density of steel.","wrong":{"1":"6.2 g/cm³ does not follow from the given dimensions.","2":"6.6 g/cm³ does not follow from the given dimensions.","4":"8.8 g/cm³ is 880/100, which ignores the cross-sectional area."}}},{"id":18,"part":"A","unit":null,"blocks":[{"t":"p","h":"Choose the option that will make the following statement FALSE:<br>A CHILD COUNTED THE NUMBER OF APPEARANCES OF THE LETTER T IN THIS SENTENCE, AND REPORTED IT CORRECTLY AS ___"}],"options":[{"key":"1","text":"TEN"},{"key":"2","text":"ELEVEN"},{"key":"3","text":"TWELVE"},{"key":"4","text":"THIRTEEN"}],"answer":"1","explanation":{"correct":"Without the blank, the sentence has 11 T's: coun<b>T</b>ed, <b>T</b>he, <b>T</b>he, le<b>tt</b>er, <b>T</b>, <b>T</b>his, sen<b>T</b>ence, repor<b>T</b>ed, i<b>T</b>, correc<b>T</b>ly. Filling the blank adds that word's own T's. ELEVEN (no T) gives 11, TWELVE (one T) gives 12, THIRTEEN (two T's) gives 13, so all three are self-consistent. <b>TEN</b> adds one T and makes 12, not 10, so it makes the statement false.","wrong":{"2":"ELEVEN has no T; the count stays at 11, so the statement is true.","3":"TWELVE adds one T, giving 12, so the statement is true.","4":"THIRTEEN adds two T's, giving 13, so the statement is true."}}},{"id":19,"part":"A","unit":null,"blocks":[{"t":"p","h":"The chart shows forest cover as percentages of total areas of 6 countries over the period 1990-2022 and their land areas (in million km²)."},{"t":"img","src":"data:image/webp;base64,","w":575,"h":276,"alt":"Line chart of percent forest cover, 1990–2020: Tanzania falls from about 60% to 51%; Russian Fed about 49–50% flat; United States about 33–34%; India rises from about 21.5% to 24%; China rises from about 17% to 23%; Australia about 17%. Land areas: Tanzania 0.9, Russian Fed 16.4, United States 9.1, India 3.0, China 9.4, Australia 7.7 million km²"},{"t":"p","h":"The maximum change in forest area in absolute terms among these countries took place in"}],"options":[{"key":"1","text":"Tanzania"},{"key":"2","text":"Russian Federation"},{"key":"3","text":"India"},{"key":"4","text":"China"}],"answer":"4","explanation":{"correct":"Absolute change = change in percentage cover × land area. China: about +6.5 percentage points × 9.4 million km² ≈ 0.6 million km². Tanzania: about −9 points × 0.9 ≈ 0.08. India: about +2.5 points × 3.0 ≈ 0.08. Russia: under 1 point, even × 16.4, is ≈ 0.1 or less. The largest absolute change is in <b>China</b>.","wrong":{"1":"Tanzania has the steepest <i>percentage</i> decline, but its land area is small (0.9 million km²).","2":"Russia is the largest country, but its percentage cover barely changes.","3":"India's gain is real but small, at roughly 0.08 million km²."}}},{"id":20,"part":"A","unit":null,"blocks":[{"t":"p","h":"A group of 54 boys and girls was made to stand in a queue as follows: a boy at the start was followed by a girl, then a boy followed by 2 girls, then a boy followed by 3 girls, and so on. The number of boys in the group was"}],"options":[{"key":"1","text":"8"},{"key":"2","text":"9"},{"key":"3","text":"10"},{"key":"4","text":"27"}],"answer":"2","explanation":{"correct":"With <i>k</i> boys the queue holds <i>k</i> + (1 + 2 + … + <i>k</i>) = <i>k</i> + <i>k</i>(<i>k</i>+1)/2 people. For <i>k</i> = 9: 9 + 45 = 54. So there are <b>9 boys</b> (and 45 girls).","wrong":{"1":"8 boys give 8 + 36 = 44 people.","3":"10 boys give 10 + 55 = 65 people.","4":"27 assumes equal numbers of boys and girls."}}},{"id":21,"part":"B","unit":6,"blocks":[{"t":"p","h":"A plant is NOT watered for seven days (day 1 - day 7). Leaf and root water potential are measured every two hours starting from day 1 till day 7. Which one of the following is LEAST LIKELY to happen?"}],"options":[{"key":"1","text":"Pre-dawn leaf water potential declines over the 7 days."},{"key":"2","text":"Leaf water potential shows a diurnal cycle of highs and lows."},{"key":"3","text":"Root water potential falls below leaf water potential at night."},{"key":"4","text":"Root water potential fluctuates between day and night."}],"answer":"3","explanation":{"correct":"Water moves passively down a water-potential gradient, soil → root → stem → leaf → air (the soil–plant–atmosphere continuum). Root Ψ therefore stays <i>higher</i> (less negative) than leaf Ψ. At night, with stomata closed, transpiration stops and the plant equilibrates towards soil Ψ; leaf Ψ rises to approach root Ψ but does not drop below it. A root Ψ below leaf Ψ would mean water flowing from leaves back to roots, which is the least likely outcome (Taiz &amp; Zeiger, <i>Plant Physiology</i>, ch. 4).","wrong":{"1":"Likely: as the soil dries, the pre-dawn leaf Ψ (which tracks soil Ψ) falls day by day.","2":"Likely: leaf Ψ drops at midday with transpiration and recovers at night.","4":"Likely: root Ψ also falls by day with xylem tension and recovers at night."}}},{"id":22,"part":"B","unit":10,"blocks":[{"t":"p","h":"Which of these traits is NOT characteristic of r-selected tree species?"}],"options":[{"key":"1","text":"Mortality and reproduction are strongly dependent on population density."},{"key":"2","text":"Tend to occupy habitats that are unpredictable and/or ephemeral."},{"key":"3","text":"Thrive in habitats where resource competition is low."},{"key":"4","text":"Have superior capabilities to colonize new habitats."}],"answer":"1","explanation":{"correct":"In MacArthur and Wilson's r/K scheme (Pianka 1970), r-selected species live in unpredictable or ephemeral habitats where populations are usually held <i>below</i> carrying capacity, often by density-<i>independent</i> catastrophes. Strong density-dependence of mortality and reproduction is the mark of <b>K-selected</b> species living near carrying capacity.","wrong":{"2":"Characteristic of r-strategists (for example pioneer trees of disturbed sites).","3":"Characteristic: r-strategists exploit uncrowded, low-competition conditions.","4":"Characteristic: high fecundity and dispersal make r-strategists good colonisers."}}},{"id":23,"part":"B","unit":7,"blocks":[{"t":"p","h":"Which one of the following neurotransmitters is synthesized in synaptic vesicles instead of being transported to the vesicle after its synthesis in the cytoplasm?"}],"options":[{"key":"1","text":"Norepinephrine"},{"key":"2","text":"Epinephrine"},{"key":"3","text":"Acetylcholine"},{"key":"4","text":"Serotonin"}],"answer":"1","explanation":{"correct":"Dopamine is made in the cytosol and loaded into vesicles by VMAT2. Dopamine β-hydroxylase (DBH) sits <i>inside</i> the vesicle lumen, so <b>norepinephrine</b> is synthesised within the vesicle itself (Kandel et al., <i>Principles of Neural Science</i>, ch. 16).","wrong":{"2":"Epinephrine is made by PNMT in the <i>cytosol</i> from NE that leaks out, and is then re-loaded into vesicles.","3":"Acetylcholine is made in the cytosol by choline acetyltransferase and loaded by VAChT.","4":"Serotonin is made in the cytosol (tryptophan hydroxylase, AADC) and loaded by VMAT2."}}},{"id":24,"part":"B","unit":3,"blocks":[{"t":"p","h":"Which one of the following statements for the <i>lac</i> operon in <i>E. coli</i> is INCORRECT?"}],"options":[{"key":"1","text":"The <i>lac</i> operon is controlled by both the Lac repressor and the activator protein, CAP."},{"key":"2","text":"The <i>lac</i> operon is highly expressed only when both lactose and glucose are absent."},{"key":"3","text":"The <i>lac</i> operon is highly expressed only when lactose is present and glucose is absent."},{"key":"4","text":"In the presence of lactose, the repressor cannot bind to the operator."}],"answer":"2","explanation":{"correct":"High expression needs two signals together: the inducer (allolactose, from lactose) to release LacI from the operator, <i>and</i> low glucose, so that cAMP–CAP activates the promoter. Without lactose the repressor stays bound, so expression is <i>not</i> high even when glucose is absent. Statement 2 is incorrect.","wrong":{"1":"Correct: negative control by LacI and positive control by cAMP–CAP.","3":"Correct: this is the condition for maximal expression.","4":"Correct: allolactose binds LacI and lowers its affinity for the operator."}}},{"id":25,"part":"B","unit":5,"blocks":[{"t":"p","h":"Which one of the following statements about the cortical reaction in sea urchins is correct?"}],"options":[{"key":"1","text":"The entry of Ca<sup>2+</sup> ions into the egg initiates development."},{"key":"2","text":"The exocytosed cortical granules during egg maturation contain the components of the zona pellucida."},{"key":"3","text":"The depolarization of the plasma membrane after sperm entry helps to block polyspermy."},{"key":"4","text":"The release of the cortical granules after sperm entry converts the vitelline membrane into the fertilization membrane which blocks polyspermy."}],"answer":"4","explanation":{"correct":"The cortical reaction is the slow block to polyspermy. A Ca<sup>2+</sup> wave released from the ER triggers cortical granule exocytosis. Granule proteases cut the vitelline-membrane links and bindin receptors, mucopolysaccharides swell the perivitelline space, and peroxidase cross-links the lifted vitelline envelope into the hardened <b>fertilization membrane</b> (Gilbert, <i>Developmental Biology</i>, fertilization chapter).","wrong":{"1":"The activating Ca<sup>2+</sup> comes mainly from internal (IP<sub>3</sub>-released ER) stores, not influx, and the statement does not describe the cortical reaction.","2":"The zona pellucida belongs to mammals, and cortical granules discharge at fertilisation, not during maturation.","3":"Membrane depolarisation is the <i>fast</i> block, a separate event from the cortical reaction."}}},{"id":26,"part":"B","unit":3,"blocks":[{"t":"p","h":"Who experimentally demonstrated \"Mutations occur randomly\"?"}],"options":[{"key":"1","text":"Alfred Hershey and Martha Chase"},{"key":"2","text":"Matthew Meselson and Franklin Stahl"},{"key":"3","text":"Salvador Luria and Max Delbrück"},{"key":"4","text":"François Jacob and Jacques Monod"}],"answer":"3","explanation":{"correct":"The fluctuation test (Luria &amp; Delbrück 1943, <i>Genetics</i> 28:491) found that the number of T1-resistant <i>E. coli</i> varied enormously between parallel cultures, far beyond Poisson variation. That fits mutations arising spontaneously and at random <i>before</i> selection, not being induced by the phage.","wrong":{"1":"Hershey–Chase (1952) showed that DNA is the genetic material of T2.","2":"Meselson–Stahl (1958) showed that DNA replication is semiconservative.","4":"Jacob–Monod (1961) proposed the operon model of gene regulation."}}},{"id":27,"part":"B","unit":10,"blocks":[{"t":"p","h":"A community of woody plants is being shaped by environmental filtering. What will be the likely local species pool of this community, if the regional species pool comprises 60 species?"}],"options":[{"key":"1","text":"100"},{"key":"2","text":"80"},{"key":"3","text":"120"},{"key":"4","text":"30"}],"answer":"4","explanation":{"correct":"In community-assembly theory, the local community is a <i>subset</i> of the regional pool: environmental (abiotic) filters remove species that cannot tolerate local conditions. The local pool must therefore be smaller than 60, and <b>30</b> is the only such option.","wrong":{"1":"A local pool cannot exceed the regional pool it is drawn from.","2":"A local pool cannot exceed the regional pool it is drawn from.","3":"A local pool cannot exceed the regional pool it is drawn from."}}},{"id":28,"part":"B","unit":10,"blocks":[{"t":"p","h":"Which one of the following is an example of dishonest signaling?"}],"options":[{"key":"1","text":"Batesian model"},{"key":"2","text":"Batesian mimic"},{"key":"3","text":"Müllerian model"},{"key":"4","text":"Müllerian mimic"}],"answer":"2","explanation":{"correct":"A Batesian mimic is palatable but copies the warning colours of a defended model, so its aposematic signal falsely advertises unprofitability. That makes it a dishonest signal.","wrong":{"1":"The Batesian model really is defended, so its signal is honest.","3":"Müllerian co-mimics are all defended, so their shared signal is honest.","4":"Müllerian co-mimics are all defended, so their shared signal is honest."}}},{"id":29,"part":"B","unit":7,"blocks":[{"t":"p","h":"How many amino acids are present in calcitonin, a calcium lowering hormone synthesized from C-cells of the human thyroid gland?"}],"options":[{"key":"1","text":"42"},{"key":"2","text":"32"},{"key":"3","text":"22"},{"key":"4","text":"12"}],"answer":"2","explanation":{"correct":"Human calcitonin is a <b>32-residue</b> peptide with a Cys1–Cys7 disulphide ring and a C-terminal prolinamide. It is cleaved from procalcitonin (116 aa) in parafollicular C cells.","wrong":{"1":"42 residues is not the length of calcitonin.","3":"22 residues is not the length of calcitonin.","4":"12 residues is not the length of calcitonin."}}},{"id":30,"part":"B","unit":6,"blocks":[{"t":"p","h":"Which of the following is LEAST suited for long-distance phloem transport of photo-assimilated carbon in plants?"}],"options":[{"key":"1","text":"Reducing sugars"},{"key":"2","text":"Mannitol"},{"key":"3","text":"Galactosyl-sucrose oligosaccharides"},{"key":"4","text":"Non-reducing sugars"}],"answer":"1","explanation":{"correct":"Phloem translocates chemically inert, <b>non-reducing</b> carbohydrates: sucrose, the raffinose-family oligosaccharides (galactosyl-sucrose: raffinose, stachyose, verbascose) and sugar alcohols such as mannitol and sorbitol. Reducing sugars such as glucose and fructose have a free aldehyde or keto group that reacts non-enzymatically with proteins and would be metabolised en route, so they are the least suited (Taiz &amp; Zeiger, ch. 11).","wrong":{"2":"Mannitol is a sugar alcohol translocated in celery, olive and other species.","3":"Raffinose-family oligosaccharides are the main transport sugars of cucurbits (polymer-trapping loaders).","4":"Non-reducing sugars, mainly sucrose, are the standard phloem cargo."}}},{"id":31,"part":"B","unit":14,"blocks":[{"t":"p","h":"Cell lysate in 1% TX100 was purified over an affinity column to isolate a complex with certain enzymatic activity. The purified enzyme complex was separated on a 10-50% continuous sucrose gradient. Shown below are the UV spectra using an absorbance filter at 280 nm or 260 nm."},{"t":"img","src":"data:image/webp;base64,","w":535,"h":397,"alt":"Two sucrose-gradient profiles from 10% to 50%. Left, A280: a modest peak in the middle of the gradient. Right, A260: a much larger peak at the same position"},{"t":"p","h":"Which one of the following combinations of molecules would generate the spectra shown above?"}],"options":[{"key":"1","text":"Protein-Protein"},{"key":"2","text":"Protein-RNA"},{"key":"3","text":"Protein-Lipid"},{"key":"4","text":"Protein-Cholesterol"}],"answer":"2","explanation":{"correct":"The complex sediments as a single species that absorbs at both wavelengths, and it absorbs much more strongly at 260 nm than at 280 nm (A260/A280 well above 1). Nucleic-acid bases absorb maximally near 260 nm, while proteins peak at 280 nm (Trp, Tyr). A co-sedimenting peak dominated by A260 points to a <b>ribonucleoprotein</b> (protein–RNA) complex, such as a ribozyme-containing RNP or telomerase.","wrong":{"1":"A protein-only complex would have A260/A280 of about 0.6 and would not be dominated by 260 nm absorbance.","3":"Lipids barely absorb at 260 or 280 nm.","4":"Cholesterol does not absorb appreciably at 260 or 280 nm."}}},{"id":32,"part":"B","unit":13,"blocks":[{"t":"p","h":"A researcher overexpresses the full-length genomic sequence of rice GAPDH gene under a CaMV35S promoter in transgenic rice. Which one of the following options can be used to confirm transgenic lines using PCR?"}],"options":[{"key":"1","text":"Using exon-specific primers of the GAPDH gene."},{"key":"2","text":"Using intron-specific primers of the GAPDH gene."},{"key":"3","text":"Amplification of the promoter region of the GAPDH gene."},{"key":"4","text":"Using CaMV35S promoter-specific forward and GAPDH-specific reverse primer."}],"answer":"4","explanation":{"correct":"The transgene is rice's own GAPDH genomic sequence, so any primer pair lying wholly inside GAPDH also amplifies the endogenous gene in every plant, transgenic or not. Only a junction amplicon, with a forward primer in the CaMV 35S promoter and a reverse primer in GAPDH, is unique to the T-DNA and identifies true transgenic lines.","wrong":{"1":"Exon primers also amplify the endogenous GAPDH locus.","2":"Intron primers also amplify the endogenous locus, since the transgene is a genomic copy with introns.","3":"The native GAPDH promoter is not part of the construct, and it exists in every rice plant anyway."}}},{"id":33,"part":"B","unit":6,"blocks":[{"t":"p","h":"Which one of the following is a correct combination of four carbon intermediates formed during C<sub>4</sub> photosynthesis in plants?"}],"options":[{"key":"1","text":"Malate and Aspartate"},{"key":"2","text":"Aspartate and Alanine"},{"key":"3","text":"Phosphoenolpyruvate and Oxaloacetate"},{"key":"4","text":"Alanine and Pyruvate"}],"answer":"1","explanation":{"correct":"PEP carboxylase fixes HCO<sub>3</sub><sup>−</sup> onto PEP (C<sub>3</sub>) to give oxaloacetate (C<sub>4</sub>). OAA is then reduced to <b>malate</b> (NADP-ME types) or transaminated to <b>aspartate</b> (NAD-ME and PEPCK types). These C<sub>4</sub> acids carry CO<sub>2</sub> to the bundle sheath. Both members of option 1 are four-carbon acids.","wrong":{"2":"Alanine is a C<sub>3</sub> compound returning from the bundle sheath.","3":"PEP is C<sub>3</sub>; only OAA is C<sub>4</sub>.","4":"Alanine and pyruvate are both C<sub>3</sub>."}}},{"id":34,"part":"B","unit":4,"blocks":[{"t":"p","h":"It was found that most people who were vaccinated with the ancestral strain of Covid-19 (Wuhan strain) were protected against the Delta variant but not against the Omicron variant. PBMCs (peripheral blood mononuclear cells) and serum were obtained from five successfully vaccinated individuals with good neutralizing antibody titres and cytotoxic (CTL) activity against the Wuhan strain-infected targets. Pooled serum was transferred into unrelated recipient \"A\" and pooled purified T cells were transferred into unrelated recipient \"B\". Which one of the following is likely to be observed?"}],"options":[{"key":"1","text":"\"A\" will be protected against both the ancestral strain and the Delta variant."},{"key":"2","text":"\"B\" will be protected against ancestral strain but not against the Delta variant."},{"key":"3","text":"\"A\" will be protected against infection with the Omicron variant."},{"key":"4","text":"\"A\" will make antibodies against interferon gamma present in the donor serum."}],"answer":"1","explanation":{"correct":"This is passive (serum) transfer of immunity. Serum carries neutralising antibodies, which block the virus without needing MHC matching. In the donors those antibodies neutralised the ancestral strain and cross-reacted with the Delta variant, so recipient A gains the same cross-protection against both.","wrong":{"2":"T cells recognise antigen only on matching MHC. Pooled T cells from unrelated donors are MHC-mismatched to recipient B, so they cannot mount a protective response in that host.","3":"The donors' antibodies failed to neutralise the Omicron variant, so transferred serum offers no protection against it.","4":"Interferon gamma in serum is a self cytokine; it is not immunogenic in the recipient and would not provoke antibodies."}}},{"id":35,"part":"B","unit":2,"blocks":[{"t":"p","h":"Which one of the following statements regarding plasmodesmata in a plant cell is INCORRECT?"}],"options":[{"key":"1","text":"They are specialized cell-to-cell junctions."},{"key":"2","text":"They are open channels that connect the cytosol of adjacent cells."},{"key":"3","text":"The plasma membranes of the adjacent cells extend continuously through each plasmodesma."},{"key":"4","text":"Plasmodesmata are extensions of chloroplast that interconnects the cytosol of the adjacent cells."}],"answer":"4","explanation":{"correct":"Plasmodesmata are membrane-lined channels through the cell wall. The plasma membrane is continuous from one cell to the next, and a strand of ER (the desmotubule) runs through the pore, creating the symplast. They have nothing to do with chloroplasts, so statement 4 is incorrect.","wrong":{"1":"Correct: they are specialised intercellular junctions, the plant analogue of gap junctions.","2":"Correct: the cytoplasmic sleeve links the cytosol of neighbouring cells.","3":"Correct: the plasma membrane is continuous through the pore."}}},{"id":36,"part":"B","unit":3,"blocks":[{"t":"p","h":"In eukaryotes, nucleosome remodelers"}],"options":[{"key":"1","text":"methylate histone H3."},{"key":"2","text":"acetylate histone H3 and H4."},{"key":"3","text":"create DNaseI hypersensitive sites."},{"key":"4","text":"degrade histone subunits."}],"answer":"3","explanation":{"correct":"ATP-dependent chromatin remodellers (SWI/SNF, ISWI, CHD, INO80) use ATP hydrolysis to slide, eject or restructure nucleosomes. Clearing nucleosomes from a stretch of DNA exposes it to nucleases, which is detected experimentally as a <b>DNaseI hypersensitive site</b> that marks active promoters and enhancers.","wrong":{"1":"Methylation of H3 is done by histone methyltransferases, not remodellers.","2":"Acetylation is carried out by histone acetyltransferases (HATs).","4":"Remodellers reposition nucleosomes; they do not degrade histones."}}},{"id":37,"part":"B","unit":14,"blocks":[{"t":"p","h":"A pulse oximeter measures the ratio between oxyhemoglobin and hemoglobin in the pulsating condition on the finger. Which combination of wavelengths can obtain a differential absorption to measure blood oxygen saturation?"}],"options":[{"key":"1","text":"Ultraviolet and Infrared"},{"key":"2","text":"Visible and Infrared"},{"key":"3","text":"Far-ultraviolet and visible"},{"key":"4","text":"Ultraviolet and far-ultraviolet"}],"answer":"2","explanation":{"correct":"Pulse oximeters use red light (~660 nm, visible) and near-infrared (~940 nm). Deoxyhaemoglobin absorbs more red light, while oxyhaemoglobin absorbs more infrared; the ratio of absorbances at the two wavelengths gives SpO<sub>2</sub>. So the pair is <b>visible and infrared</b>.","wrong":{"1":"UV is absorbed by tissue and is not used, nor safe, for transmission oximetry.","3":"Far-UV is strongly absorbed and damaging; it does not pass through a finger.","4":"Neither UV nor far-UV is used in oximetry."}}},{"id":38,"part":"B","unit":7,"blocks":[{"t":"p","h":"Which one of the following statements regarding mammalian innate immunity is INCORRECT?"}],"options":[{"key":"1","text":"Pattern recognition receptors (PRRs) are a component of innate immunity."},{"key":"2","text":"Serum complement proteins are part of innate immunity."},{"key":"3","text":"Innate immunity has only a narrow range of specificity."},{"key":"4","text":"The outcome of innate immunity is the rapid recognition and phagocytosis or destruction of the pathogen."}],"answer":"3","explanation":{"correct":"Innate immunity recognises conserved pathogen-associated molecular patterns through a limited, germline-encoded set of PRRs. This gives it <i>broad</i>, not narrow, specificity: one receptor (for example TLR4) detects a molecular class shared by many microbes. Statement 3 is therefore incorrect.","wrong":{"1":"Correct: PRRs such as TLRs and NOD-like receptors are central to innate immunity.","2":"Correct: complement is a humoral arm of innate immunity.","4":"Correct: rapid recognition followed by phagocytosis or lysis is the hallmark of innate responses."}}},{"id":39,"part":"B","unit":14,"blocks":[{"t":"p","h":"A student counts the number of seeds produced by ten different haploid Arabidopsis plants and obtains the following data: 0, 5, 15, 25, 100, 150, 200, 600, 1500, 3000. Which one of the following is the best measure of central tendency for summarizing the above data?"}],"options":[{"key":"1","text":"Mean"},{"key":"2","text":"Median"},{"key":"3","text":"Mode"},{"key":"4","text":"Standard deviation"}],"answer":"2","explanation":{"correct":"The data are strongly right-skewed, spanning 0 to 3000 with a few very large values. The mean is pulled towards those extremes and misrepresents a typical plant, whereas the <b>median</b> (here 125) is robust to outliers and best summarises the centre of a skewed distribution.","wrong":{"1":"The mean (about 560) is inflated by the 1500 and 3000 outliers.","3":"The mode is undefined here; every value occurs once.","4":"Standard deviation measures spread, not central tendency."}}},{"id":40,"part":"B","unit":3,"blocks":[{"t":"p","h":"A DNA molecule is completely transcribed into messenger RNA by an RNA polymerase. The base composition of the DNA template strand is G = 24.1%; C = 18.5%; A = 24.6%; T = 32.8%. The base composition of the newly synthesized RNA molecule is:"}],"options":[{"key":"1","text":"G = 24.1%, C = 18.5%, A = 24.6%, U = 32.8%"},{"key":"2","text":"G = 24.6%, C = 24.1%, A = 18.5%, U = 32.8%"},{"key":"3","text":"G = 18.5%, C = 24.1%, A = 32.8%, U = 24.6%"},{"key":"4","text":"G = 32.8%, C = 24.6%, A = 18.5%, U = 24.1%"}],"answer":"3","explanation":{"correct":"RNA is complementary (and antiparallel) to the template strand. Each template base pairs with its complement in the transcript: template G → C, C → G, A → U, T → A. So from G = 24.1% template we get C = 24.1% RNA; C = 18.5% → G = 18.5%; A = 24.6% → U = 24.6%; T = 32.8% → A = 32.8%. That gives <b>G = 18.5%, C = 24.1%, A = 32.8%, U = 24.6%</b>.","wrong":{"1":"This just copies the template composition and replaces T with U; it does not take the complement.","2":"The base-pairing assignments are scrambled.","4":"The base-pairing assignments are scrambled."}}},{"id":41,"part":"B","unit":1,"blocks":[{"t":"p","h":"In the representation of the di-peptide shown below, the superscript '−1' denotes the atom of the previous amino acid while '+1' denotes the atom of the next amino acid. The atomic coordinates of how many AND which of the following atoms are required to uniquely define the torsion angles, φ and ψ of the Ramachandran plot?"},{"t":"img","src":"data:image/webp;base64,","w":285,"h":185,"alt":"A dipeptide backbone showing C(−1) carbonyl, then N, Cα and the carbonyl C of the central residue, then N(+1), with the side chain on Cα"}],"options":[{"key":"1","text":"4 atoms; C<sup>−1</sup>, N, Cα, C for φ; N, Cα, C, N<sup>+1</sup> for ψ"},{"key":"2","text":"2 atoms; N and Cα for φ; Cα and C for ψ"},{"key":"3","text":"4 atoms; H, N, Cα, C for φ; N, Cα, C, O for ψ"},{"key":"4","text":"3 atoms; C<sup>−1</sup>, N, Cα for φ; Cα, C, N<sup>+1</sup> for ψ"}],"answer":"1","explanation":{"correct":"A torsion angle is defined by four consecutive atoms. φ is the rotation about the N–Cα bond, set by <b>C<sup>−1</sup>, N, Cα, C</b>; ψ is the rotation about the Cα–C bond, set by <b>N, Cα, C, N<sup>+1</sup></b>. So four distinct atoms (C<sup>−1</sup>, N, Cα, C) plus N<sup>+1</sup> are involved, and option 1 lists them correctly.","wrong":{"2":"Two atoms define only a bond, not a dihedral angle.","3":"H and O are not the atoms that define the backbone φ/ψ dihedrals (the amide H and carbonyl O are not the flanking backbone atoms used).","4":"Three atoms define a bond angle, not a torsion angle."}}},{"id":42,"part":"B","unit":3,"blocks":[{"t":"p","h":"What is the correct order in which the following proteins are recruited during DNA double strand break repair in prokaryotes?"}],"options":[{"key":"1","text":"RecA, RecBCD, Ssb, DNA Pol III, DNA Ligase"},{"key":"2","text":"Ssb, RecA, RecBCD, DNA Pol III, DNA Ligase"},{"key":"3","text":"RecBCD, RecA, Ssb, DNA Pol III, DNA Ligase"},{"key":"4","text":"RecBCD, Ssb, RecA, DNA Pol III, DNA Ligase"}],"answer":"4","explanation":{"correct":"In <i>E. coli</i> recombinational (RecBCD-pathway) repair of a double-strand break, <b>RecBCD</b> first binds the duplex end and resects it, generating a 3′ single-stranded tail. <b>SSB (Ssb)</b> coats and protects that ssDNA, then <b>RecA</b> is loaded onto it (RecBCD facilitates RecA loading at a Chi site) to catalyse strand invasion. After branch migration and resolution, <b>DNA Pol III</b> fills the gap and <b>DNA ligase</b> seals it. The order is RecBCD → Ssb → RecA → Pol III → Ligase.","wrong":{"1":"Puts RecA first; RecBCD must process the end and SSB must coat the ssDNA before RecA loads.","2":"Puts SSB first; the double-strand end must be resected by RecBCD before any single strand exists for SSB to bind.","3":"Reverses Ssb and RecA: SSB coats the resected ssDNA before RecA displaces it during filament formation."}}},{"id":43,"part":"B","unit":1,"blocks":[{"t":"p","h":"Retinal rod cell cGMP-phosphodiesterase is an enzyme with subunit structure as:"}],"options":[{"key":"1","text":"αβγ"},{"key":"2","text":"αβγ<sub>2</sub>"},{"key":"3","text":"αβ<sub>2</sub>γ"},{"key":"4","text":"α<sub>2</sub>βγ"}],"answer":"2","explanation":{"correct":"Rod PDE6 is a catalytic αβ heterodimer held in check by two identical inhibitory γ subunits, giving the composition <b>αβγ<sub>2</sub></b>. Light-activated transducin (Tα-GTP) pulls the γ subunits off, releasing catalytic activity and lowering cGMP.","wrong":{"1":"αβγ omits the second inhibitory γ subunit.","3":"The two catalytic subunits are α and β (one each), not two β.","4":"The catalytic subunits are α and β (one each), not two α."}}},{"id":44,"part":"B","unit":10,"blocks":[{"t":"p","h":"Which one of the following concepts can explain host-parasite co-evolution?"}],"options":[{"key":"1","text":"Kin selection"},{"key":"2","text":"Red Queen hypothesis"},{"key":"3","text":"Runaway selection"},{"key":"4","text":"Handicap principle"}],"answer":"2","explanation":{"correct":"The <b>Red Queen hypothesis</b> (Van Valen 1973) describes the perpetual reciprocal arms race between antagonists: hosts evolve resistance, parasites evolve counter-adaptations, and each must keep evolving just to maintain relative fitness. It is the standard framework for host–parasite coevolution and for the maintenance of sex.","wrong":{"1":"Kin selection explains altruism among relatives (Hamilton's rule).","3":"Runaway (Fisherian) selection explains the exaggeration of mate-choice ornaments.","4":"The handicap principle explains honest signalling of quality in sexual selection."}}},{"id":45,"part":"B","unit":5,"blocks":[{"t":"p","h":"If chimeric mouse embryos were generated using GFP-expressing embryonic stem cells and RFP-expressing induced pluripotent stem cells, which one of the following tissues from any resulting embryos will not express any fluorescent protein?"}],"options":[{"key":"1","text":"Brain"},{"key":"2","text":"Heart"},{"key":"3","text":"Intestine"},{"key":"4","text":"Placenta"}],"answer":"4","explanation":{"correct":"Both ES cells and iPS cells are pluripotent and contribute to the three embryonic germ layers (the fetus proper), so brain, heart and intestine would be a GFP/RFP mix. The <b>placenta</b>, however, derives from the trophectoderm and primitive endoderm (extra-embryonic lineages), to which injected ES/iPS cells normally do not contribute, so it expresses neither fluorophore.","wrong":{"1":"Brain (ectoderm) is colonised by the pluripotent cells.","2":"Heart (mesoderm) is colonised by the pluripotent cells.","3":"Intestine (endoderm) is colonised by the pluripotent cells."}}},{"id":46,"part":"B","unit":6,"blocks":[{"t":"p","h":"Which one of the following correctly describes 'Dark Reversion' of phytochromes?"}],"options":[{"key":"1","text":"Conversion of P<sub>R</sub> to P<sub>FR</sub>"},{"key":"2","text":"Conversion of P<sub>FR</sub> to P<sub>R</sub>"},{"key":"3","text":"Export of P<sub>FR</sub> from cytosol to nucleus"},{"key":"4","text":"Export of P<sub>R</sub> from cytosol to nucleus"}],"answer":"2","explanation":{"correct":"Phytochrome exists as red-absorbing P<sub>R</sub> and far-red-absorbing P<sub>FR</sub>. P<sub>FR</sub> (the active form) can revert to the inactive P<sub>R</sub> slowly in darkness, without light, by thermal relaxation: <b>dark reversion</b> of P<sub>FR</sub> to P<sub>R</sub>.","wrong":{"1":"P<sub>R</sub> → P<sub>FR</sub> is driven by red <i>light</i>, not darkness.","3":"Nuclear import of P<sub>FR</sub> is a light-triggered signalling step, not dark reversion.","4":"P<sub>R</sub> is cytosolic and is not the species that reverts."}}},{"id":47,"part":"B","unit":6,"blocks":[{"t":"p","h":"For maintaining hydraulic conductance, tree stems appear to trade-off vessel diameter with"}],"options":[{"key":"1","text":"strength of the stem."},{"key":"2","text":"stem length."},{"key":"3","text":"heartwood volume."},{"key":"4","text":"vessel length."}],"answer":"1","explanation":{"correct":"Wide xylem vessels conduct far more efficiently (flow scales with the fourth power of radius, Hagen–Poiseuille), but wood packed with large, thin-walled, wide-lumen conduits is mechanically weaker and more prone to vessel implosion. So a stem gains hydraulic conductance at the cost of <b>mechanical strength</b>: the classic efficiency-versus-safety/strength trade-off of xylem (Hacke et al. 2001).","wrong":{"2":"Stem length is a whole-plant architectural trait, not what vessel diameter is traded against for conductance.","3":"Heartwood is non-conducting; its volume does not trade against vessel diameter.","4":"Vessel length tends to increase <i>with</i> diameter (they are positively correlated), so it is not the quantity sacrificed to gain conductance."}}},{"id":48,"part":"B","unit":9,"blocks":[{"t":"p","h":"Andaman and Nicobar archipelago are part of which biodiversity hotspots?"}],"options":[{"key":"1","text":"Andaman - Indo-Burma; Nicobar - Sundaland"},{"key":"2","text":"Andaman - Sundaland; Nicobar - Indo-Burma"},{"key":"3","text":"Andaman - Indo-Burma; Nicobar - Indo-Burma"},{"key":"4","text":"Andaman - Sundaland; Nicobar - Sundaland"}],"answer":"1","explanation":{"correct":"The Andaman Islands fall within the <b>Indo-Burma</b> hotspot, while the Nicobar Islands belong to the <b>Sundaland</b> hotspot. This split reflects their different biogeographic affinities, the Andamans to mainland Southeast Asia and the Nicobars to the Sunda shelf flora and fauna.","wrong":{"2":"The affinities are reversed.","3":"The Nicobars are Sundaland, not Indo-Burma.","4":"The Andamans are Indo-Burma, not Sundaland."}}},{"id":49,"part":"B","unit":10,"blocks":[{"t":"p","h":"Select the statement that describes guild coevolution, also known as diffuse coevolution."}],"options":[{"key":"1","text":"One species uses the other as a resource."},{"key":"2","text":"Two species coevolve reciprocally, but only to each other."},{"key":"3","text":"Several species are involved in coevolutionary interactions."},{"key":"4","text":"A species escapes association from a predator and diversifies. Later, a different predator adapts to the host and diversifies."}],"answer":"3","explanation":{"correct":"Diffuse (guild) coevolution occurs when a species evolves in response to a <i>group</i> of other species rather than to a single partner, so that selection on any trait depends on <b>several interacting species</b> at once. This contrasts with pairwise (specific) coevolution.","wrong":{"1":"A one-way resource relationship is exploitation, not coevolution.","2":"Reciprocal evolution between just two species is pairwise (specific) coevolution.","4":"That sequential, one-partner-at-a-time scenario is escape-and-radiate coevolution, not diffuse coevolution."}}},{"id":50,"part":"B","unit":1,"blocks":[{"t":"p","h":"Which one of the following statements regarding the structure of water molecule is correct?"}],"options":[{"key":"1","text":"The oxygen atom in water is in sp<sup>3</sup> hybridization, with an H-O-H angle of 109.5°."},{"key":"2","text":"The oxygen atom in water is in sp<sup>2</sup> hybridization, with an H-O-H angle of 120°."},{"key":"3","text":"The oxygen atom in water is in sp<sup>3</sup> hybridization, with an H-O-H angle of 104.5°."},{"key":"4","text":"The oxygen atom in water is in sp<sup>2</sup> hybridization, with an H-O-H angle of 90°."}],"answer":"3","explanation":{"correct":"Oxygen in water is <b>sp<sup>3</sup></b> hybridised with four electron domains (two bonding, two lone pairs). Lone-pair repulsion compresses the ideal tetrahedral angle of 109.5° to the observed <b>104.5°</b>.","wrong":{"1":"sp<sup>3</sup> is right, but lone-pair repulsion makes the angle 104.5°, not the ideal 109.5°.","2":"Water is sp<sup>3</sup>, not sp<sup>2</sup>, and the angle is not 120°.","4":"Water is sp<sup>3</sup>, not sp<sup>2</sup>, and the angle is not 90°."}}},{"id":51,"part":"B","unit":1,"blocks":[{"t":"p","h":"Given below are Ramachandran plots for four different proteins."},{"t":"img","src":"data:image/webp;base64,","w":636,"h":551,"alt":"Four Ramachandran plots A–D. Plots A and B each have a large cluster of points in the upper-left β-sheet region (ψ around +120° to +150°) as well as points in the α region; plots C and D have their dense cluster in the lower-left α-helical basin (φ about −70°, ψ about −40°) with few points in the β region"},{"t":"p","h":"Choose the correct pair of proteins, both of which are predominantly alpha helical in nature."}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"A and C"},{"key":"3","text":"B and D"},{"key":"4","text":"C and D"}],"answer":"4","explanation":{"correct":"On a Ramachandran plot, α-helical residues cluster around φ ≈ −60°, ψ ≈ −45° (lower-left), while β-strand residues sit at φ ≈ −120°, ψ ≈ +120° (upper-left). Plots <b>C and D</b> have their dense population in the α-helical basin and few points in the β region, so those two proteins are predominantly α-helical.","wrong":{"1":"A and B each carry a large cluster in the upper-left β-sheet region, so they are not predominantly helical.","2":"A has a prominent β-sheet cluster, so this pair is not both predominantly helical.","3":"B has a prominent β-sheet cluster, so this pair is not both predominantly helical."}}},{"id":52,"part":"B","unit":5,"blocks":[{"t":"p","h":"In <i>Caenorhabditis elegans</i>, blastomere identity occurs both through conditional and autonomous modes of cell specification. Which one of the following options is a correct statement in this regard?"}],"options":[{"key":"1","text":"If the AB and P1 blastomeres are experimentally separated, the AB cell will generate all cells it would normally make."},{"key":"2","text":"When AB divides to form daughter cells, ABp becomes different from ABa through its interaction with the P2 cell."},{"key":"3","text":"The specification of AB cell is determined by the presence of cytoplasmic determinants."},{"key":"4","text":"The P2 cell produces a morphogen for the determination of the ABp cell."}],"answer":"2","explanation":{"correct":"ABa and ABp are initially equivalent. <b>ABp</b> contacts the P2 cell, which presents the Delta-ligand APX-1 to the GLP-1 (Notch) receptor on ABp; this conditional (inductive) signal makes ABp different from ABa. So AB fates are specified conditionally by cell contact.","wrong":{"1":"AB is specified conditionally, so once isolated from P1 it loses the inductive cues and does <i>not</i> make its full normal set of cells.","3":"AB specification is conditional (contact-dependent), not driven by inherited cytoplasmic determinants; those operate in the P (germline) lineage.","4":"P2 signals through membrane-bound Delta (APX-1), a contact-dependent ligand, not a secreted diffusible morphogen."}}},{"id":53,"part":"B","unit":3,"blocks":[{"t":"p","h":"Which one of the following options has the correct set of components for assaying reverse transcriptase activity?"}],"options":[{"key":"1","text":"RNA primer, dNTPs, buffer, primase, DNA template"},{"key":"2","text":"DNA primer, NTPs, buffer, DNA template"},{"key":"3","text":"DNA primer, dNTPs, buffer, RNA template"},{"key":"4","text":"RNA primer, NTPs, buffer, RNA template"}],"answer":"3","explanation":{"correct":"Reverse transcriptase makes DNA from an RNA template. The assay needs an <b>RNA template</b>, a primer with a free 3′-OH (a DNA primer is standard), <b>dNTPs</b> (DNA is being synthesised) and buffer. Option 3 lists DNA primer, dNTPs, buffer and RNA template.","wrong":{"1":"Primase is not required, and a DNA product needs dNTPs with an RNA template, not this mix.","2":"A DNA template with NTPs describes transcription, not reverse transcription.","4":"NTPs (not dNTPs) would make RNA; reverse transcription needs dNTPs."}}},{"id":54,"part":"B","unit":3,"blocks":[{"t":"p","h":"In eukaryotic cells, DNA replication is restricted to the S phase of the cell cycle because"}],"options":[{"key":"1","text":"DNA polymerase is present only in the S phase of the cell cycle."},{"key":"2","text":"Origin recognition complex (ORC) recognizes origin only in the S phase."},{"key":"3","text":"MCM helicases get activated in the S phase of the cell cycle."},{"key":"4","text":"MCM helicases get activated in the G1 phase of the cell cycle."}],"answer":"3","explanation":{"correct":"Origins are <i>licensed</i> in G1 by loading inactive MCM2-7 double hexamers (pre-replicative complex). They are only <b>activated in S phase</b>, when S-CDK and DDK trigger helicase firing and polymerase loading. Separating licensing (G1) from firing (S) ensures each origin fires once per cycle, restricting replication to S phase.","wrong":{"1":"DNA polymerases are present throughout the cycle; their recruitment is regulated.","2":"ORC binds origins throughout the cycle, not only in S phase.","4":"MCMs are <i>loaded</i> in G1 but remain inactive; they are activated in S phase."}}},{"id":55,"part":"B","unit":3,"blocks":[{"t":"p","h":"Which one of the following does NOT occur during ribosome-associated quality control of damaged mRNA?"}],"options":[{"key":"1","text":"mRNA degradation"},{"key":"2","text":"Nascent protein degradation"},{"key":"3","text":"Disengagement of ribosome from mRNA"},{"key":"4","text":"Ribosome-mRNA monosome degradation"}],"answer":"4","explanation":{"correct":"In ribosome-associated quality control, a ribosome stalled on aberrant mRNA is split into subunits; the faulty mRNA is degraded (no-go/non-stop decay) and the incomplete nascent chain is ubiquitinated (by RQC factors such as Ltn1) and degraded. The ribosome itself is recycled, not destroyed, so <b>degradation of the ribosome–mRNA monosome</b> does not occur.","wrong":{"1":"mRNA degradation does occur (no-go / non-stop decay).","2":"Nascent-chain degradation does occur via RQC ubiquitination.","3":"Subunit dissociation (ribosome rescue) does occur."}}},{"id":56,"part":"B","unit":7,"blocks":[{"t":"p","h":"In which one of the following stages pontogeniculo-occipital (PGO) spikes are found in human EEG recordings?"}],"options":[{"key":"1","text":"Immediately before and during REM sleep"},{"key":"2","text":"Non-REM sleep stage 2"},{"key":"3","text":"Awake condition"},{"key":"4","text":"Non-REM sleep stage 4"}],"answer":"1","explanation":{"correct":"PGO waves are phasic bursts that originate in the pons and propagate to the lateral geniculate and occipital cortex. They appear just before and throughout <b>REM sleep</b>, heralding and accompanying the dreaming state.","wrong":{"2":"N2 is marked by sleep spindles and K-complexes, not PGO waves.","3":"PGO waves are a sleep phenomenon, absent in the alert waking state.","4":"N3/N4 (slow-wave sleep) is dominated by delta waves, not PGO spikes."}}},{"id":57,"part":"B","unit":4,"blocks":[{"t":"p","h":"Which one of the following statements correctly explains the function of a GTPase activating protein (GAP) in the regulation of heterotrimeric G proteins in plants?"}],"options":[{"key":"1","text":"It activates Gβ protein."},{"key":"2","text":"It inactivates Gα protein."},{"key":"3","text":"It directly inhibits ligand binding to GPCR."},{"key":"4","text":"It leads to the dissociation of Gα from Gβ/Gγ subunits."}],"answer":"2","explanation":{"correct":"A GAP accelerates the intrinsic GTPase activity of Gα, speeding GTP hydrolysis to GDP. Gα-GDP is the inactive form, which re-associates with Gβγ. So a GAP <b>inactivates Gα</b> and terminates signalling (in plants, RGS1 is the GAP for the Gα subunit GPA1).","wrong":{"1":"GAPs act on the GTPase (Gα), not on Gβ.","3":"GAPs act downstream on Gα; they do not block ligand binding to the receptor.","4":"Promoting GTP hydrolysis favours re-<i>association</i> of Gα with Gβγ, not dissociation."}}},{"id":58,"part":"B","unit":5,"blocks":[{"t":"p","h":"The following are sketches of wild-type and mutant (I - III) embryos of <i>Drosophila melanogaster</i>."},{"t":"img","src":"data:image/webp;base64,","w":827,"h":152,"alt":"Dorsoventral axis sketches with a D (dorsal)–V (ventral) and A–P cross at the left. Wild type shows normal dorsal and ventral regions; mutants I, II and III show progressively more dorsalized or ventralized egg/embryo shapes, with III strongly ventralized (expanded dark ventral region)"},{"t":"p","h":"Which one of the following options represents a correct match between the gene and its loss of function phenotype?"}],"options":[{"key":"1","text":"dorsal: I"},{"key":"2","text":"torpedo: III"},{"key":"3","text":"gurken: II"},{"key":"4","text":"cactus: III"}],"answer":"3","explanation":{"correct":"Dorsoventral patterning depends on the Gurken–Torpedo (EGFR) signal in the oocyte and the Dorsal–Cactus system in the embryo. Loss of <b>gurken</b> (or of its receptor <i>torpedo</i>) removes the dorsalising EGFR signal, so the egg is <b>ventralised</b>, matching the strongly ventralised mutant. The keyed answer pairs <i>gurken</i> with phenotype II.","wrong":{"1":"Loss of <i>dorsal</i> gives a <i>dorsalised</i> embryo (no ventral structures), which does not match the phenotype shown as I here.","2":"<i>torpedo</i> (EGFR) loss ventralises like <i>gurken</i>, but the keyed match for the strongly ventralised embryo is <i>gurken</i>:II, not torpedo:III.","4":"<i>cactus</i> loss frees Dorsal and <i>ventralises</i> the embryo, so it does not match a dorsalised phenotype."},"notes":["The OCR of the figure labels is imperfect; the published key is option 3 (gurken : II). Treat the figure identifications above as the intended matches."]}},{"id":59,"part":"B","unit":6,"blocks":[{"t":"p","h":"Select the correct combination of terms from plant breeding systems that represents selfing or promote selfing."}],"options":[{"key":"1","text":"Autogamy and allogamy"},{"key":"2","text":"Cleistogamy and geitonogamy"},{"key":"3","text":"Geitonogamy and allogamy"},{"key":"4","text":"Autogamy and herkogamy"}],"answer":"2","explanation":{"correct":"Autogamy is self-pollination within a flower; cleistogamy (self-pollination in unopened flowers) guarantees it; geitonogamy is pollination between two flowers of the same plant, which is genetically still selfing. <b>Cleistogamy and geitonogamy</b> both represent or promote selfing.","wrong":{"1":"Allogamy is cross-pollination, the opposite of selfing.","3":"Allogamy is outcrossing, so this pair is mixed.","4":"Herkogamy (spatial separation of anther and stigma) <i>prevents</i> selfing and promotes outcrossing."}}},{"id":60,"part":"B","unit":8,"blocks":[{"t":"p","h":"Which one of the following statements regarding principles of linkage mapping in plants is correct?"}],"options":[{"key":"1","text":"Genetic markers would always show higher recombination frequencies when they are closer to each other than if they are far apart."},{"key":"2","text":"The genetic distance between two markers is a true representation of the physical distance between them."},{"key":"3","text":"An ideal mapping population for a self-pollinating species is generated using polymorphic parents that are inbred lines."},{"key":"4","text":"An F2 mapping population would segregate in a 1:2:1 ratio for a dominant marker."}],"answer":"3","explanation":{"correct":"A good mapping population needs parents that are homozygous (inbred) and <b>polymorphic</b> at the marker loci, so that every segregating marker can be scored unambiguously in the progeny. For a self-pollinating species, crossing two such inbred lines is the ideal design.","wrong":{"1":"Closer markers show <i>lower</i> recombination frequencies, not higher.","2":"Genetic distance (recombination) is not uniform along a chromosome; it varies with local recombination rate, so it is not a true measure of physical distance.","4":"A codominant marker segregates 1:2:1 in F2; a <i>dominant</i> marker scores 3:1 because heterozygotes look like the dominant homozygote."}}},{"id":61,"part":"B","unit":14,"blocks":[{"t":"p","h":"In rate-zonal centrifugation, a mixture is spun just long enough to separate molecules that differ in mass but may be similar in shape and density. Which one of the following options represents the component that is typically used to create a gradient in this technique?"}],"options":[{"key":"1","text":"phospholipids"},{"key":"2","text":"sucrose"},{"key":"3","text":"KCl"},{"key":"4","text":"starch"}],"answer":"2","explanation":{"correct":"Rate-zonal separation uses a pre-formed density gradient, most commonly a <b>sucrose</b> gradient (for example 5–20% or 10–50%). Samples are layered on top and sediment as bands according to their sedimentation coefficient (mass/shape), being stopped before they reach their equilibrium density.","wrong":{"1":"Phospholipids are not used to form separation gradients.","3":"CsCl (not KCl) is used, but for <i>equilibrium (isopycnic)</i> density-gradient runs, not rate-zonal.","4":"Starch is not a standard gradient medium for this purpose."}}},{"id":62,"part":"B","unit":10,"blocks":[{"t":"p","h":"Which one of the following options includes all plants that are major non-native invaders of aquatic ecosystems in India?"}],"options":[{"key":"1","text":"<i>Parthenium hysterophorus</i>, <i>Pontederia crassipes</i>, <i>Lantana camara</i>"},{"key":"2","text":"<i>Salvinia molesta</i>, <i>Prosopis juliflora</i>, <i>Mikania micrantha</i>"},{"key":"3","text":"<i>Nelumbo nucifera</i>, <i>Pogostemon erectus</i>, <i>Hygrophila serpyllum</i>"},{"key":"4","text":"<i>Pontederia crassipes</i>, <i>Salvinia molesta</i>, <i>Alternanthera philoxeroides</i>"}],"answer":"4","explanation":{"correct":"All three in option 4 are invasive <i>aquatic</i> weeds in India: <i>Pontederia crassipes</i> (water hyacinth, formerly <i>Eichhornia</i>), <i>Salvinia molesta</i> (giant salvinia) and <i>Alternanthera philoxeroides</i> (alligator weed).","wrong":{"1":"<i>Parthenium</i> and <i>Lantana</i> are terrestrial invaders, not aquatic.","2":"<i>Prosopis juliflora</i> and <i>Mikania micrantha</i> are terrestrial/climbing invaders.","3":"<i>Nelumbo nucifera</i> (lotus) is native, and these are not major aquatic invaders."}}},{"id":63,"part":"B","unit":7,"blocks":[{"t":"p","h":"How many times are sound waves amplified in the middle ear of a human?"}],"options":[{"key":"1","text":"16-18"},{"key":"2","text":"6 - 8"},{"key":"3","text":"9 - 12"},{"key":"4","text":"2 -4"}],"answer":"1","explanation":{"correct":"The middle ear matches sound from air to the fluid of the cochlea. The main gain is the ratio of the tympanic membrane area to the oval window area (about 17:1), with a small added lever action of the ossicles, giving an overall pressure amplification of roughly <b>16–18 fold</b> (about 20–22, or ~27 dB, by common textbook figures).","wrong":{"2":"6–8 fold understates the area-ratio gain.","3":"9–12 fold understates the combined area and lever gain.","4":"2–4 fold is far too small."}}},{"id":64,"part":"B","unit":9,"blocks":[{"t":"p","h":"Select the geological time where some of the major events, like an increase in marine diversity, dominance of gymnosperms, diversification of synapsids (including the emergence of first dinosaurs), and first mammal-like forms, occurred."}],"options":[{"key":"1","text":"Cretaceous"},{"key":"2","text":"Jurassic"},{"key":"3","text":"Triassic"},{"key":"4","text":"Carboniferous"}],"answer":"3","explanation":{"correct":"The <b>Triassic</b> (~252–201 Mya) saw marine faunas recover and diversify after the end-Permian extinction, gymnosperms dominate the flora, the first dinosaurs appear, and the first mammaliaforms (mammal-like cynodonts) arise.","wrong":{"1":"The Cretaceous ended the age of dinosaurs and saw flowering plants radiate.","2":"The Jurassic is the heyday of large dinosaurs, after their Triassic origin.","4":"The Carboniferous is the age of coal swamps and the first amniotes, before the events listed."}}},{"id":65,"part":"B","unit":2,"blocks":[{"t":"p","h":"Which one of the following activities is associated with Mitochondria-associated ER membranes (MAM)?"}],"options":[{"key":"1","text":"Protein glycosylation"},{"key":"2","text":"ATP synthesis"},{"key":"3","text":"Phospholipid metabolism"},{"key":"4","text":"Iron-sulphur cluster assembly"}],"answer":"3","explanation":{"correct":"MAMs are contact sites where the ER closely apposes mitochondria. They are hubs for Ca<sup>2+</sup> transfer and for <b>phospholipid metabolism</b>, the exchange and processing of phosphatidylserine, phosphatidylethanolamine and phosphatidylcholine between the two organelles.","wrong":{"1":"N-linked glycosylation occurs in the ER lumen and Golgi, not specifically at MAMs.","2":"ATP synthesis occurs at the inner mitochondrial membrane.","4":"Fe-S cluster assembly occurs in the mitochondrial matrix (ISC machinery), not at MAMs."}}},{"id":66,"part":"B","unit":5,"blocks":[{"t":"p","h":"In animal cells, typically which organelle is only provided by the sperm to the oocyte following fertilization?"}],"options":[{"key":"1","text":"Nucleolus"},{"key":"2","text":"Peroxisomes"},{"key":"3","text":"Mitochondria"},{"key":"4","text":"Centrioles"}],"answer":"4","explanation":{"correct":"The oocyte lacks functional centrioles; it is the <b>sperm</b> that contributes the centriole, which organises the first mitotic spindle of the zygote. Mitochondria, by contrast, are inherited maternally.","wrong":{"1":"The nucleolus reassembles in the zygote; it is not a sperm-donated organelle.","2":"Peroxisomes are present in the egg and not uniquely paternal.","3":"Mitochondria are inherited from the egg (maternal), with sperm mitochondria usually destroyed."}}},{"id":67,"part":"B","unit":8,"blocks":[{"t":"p","h":"<i>Brassica juncea</i> has bisexual flowers. A mutation in the mitochondria leads to cytoplasmic male sterility (CMS). CMS can be restored by a restorer of fertility gene (Rf) which is a nuclear gene. Fertility restoration is a dominant phenotype. A CMS line is crossed to a homozygous Rf line. The obtained F1 progeny is self-pollinated. What percentage of F2 progeny will be male sterile?"}],"options":[{"key":"1","text":"0"},{"key":"2","text":"25"},{"key":"3","text":"75"},{"key":"4","text":"100"}],"answer":"2","explanation":{"correct":"The F1 all inherit sterile (CMS) cytoplasm from the female parent and are Rf/rf, so they are fertile (Rf is dominant). On selfing, the nuclear genotypes segregate 1 RfRf : 2 Rfrf : 1 rrff. Only rr plants (<b>25%</b>) lack a restorer and, with the CMS cytoplasm they all carry, are male sterile.","wrong":{"1":"The rr quarter has no restorer, so some F2 are sterile.","3":"75% are fertile (those carrying at least one Rf), not sterile.","4":"The three-quarters carrying Rf are fertile, so not all are sterile."}}},{"id":68,"part":"B","unit":6,"blocks":[{"t":"p","h":"Which one of the following represents the predominant source organ during phloem translocation in healthy plants?"}],"options":[{"key":"1","text":"Roots"},{"key":"2","text":"Developing fruits"},{"key":"3","text":"Immature leaves"},{"key":"4","text":"Mature leaves"}],"answer":"4","explanation":{"correct":"Sources export photosynthate; sinks import it. <b>Mature leaves</b> are net photosynthetic exporters and are the main sources that load sucrose into the phloem.","wrong":{"1":"Roots are storage sinks (or re-mobilising sources only in special cases), not the main source in a healthy growing plant.","2":"Developing fruits are strong sinks.","3":"Immature leaves are sinks that import carbon until they transition to sources."}}},{"id":69,"part":"B","unit":9,"blocks":[{"t":"p","h":"In 2007, scientists reported the fossil of a deer-like animal in Kashmir, India which is considered the most recent terrestrial ancestor of whales. The name of this fossil is"}],"options":[{"key":"1","text":"Jainosaurus."},{"key":"2","text":"Indohyus."},{"key":"3","text":"Rajasaurus."},{"key":"4","text":"Indosuchus."}],"answer":"2","explanation":{"correct":"<b><i>Indohyus</i></b>, a small Eocene raoellid artiodactyl from Kashmir (Thewissen et al. 2007, <i>Nature</i>), shares ear and bone features with cetaceans and is regarded as a close terrestrial relative of whales.","wrong":{"1":"<i>Jainosaurus</i> is a titanosaurian dinosaur.","3":"<i>Rajasaurus</i> is an abelisaurid dinosaur from India.","4":"<i>Indosuchus</i> is another Indian theropod dinosaur."}}},{"id":70,"part":"B","unit":1,"blocks":[{"t":"p","h":"Which one of the following pairs correctly matches the enzyme with its allosteric activator?"}],"options":[{"key":"1","text":"Phosphofructokinase : Citrate"},{"key":"2","text":"Pyruvate dehydrogenase : NADH"},{"key":"3","text":"Pyruvate carboxylase : ADP"},{"key":"4","text":"Pyruvate kinase : Fructose-1,6-bisphosphate"}],"answer":"4","explanation":{"correct":"<b>Pyruvate kinase</b> is feed-forward activated by <b>fructose-1,6-bisphosphate</b>, the product of the upstream PFK step. This coordinates flux: more F1,6BP signals the last glycolytic step to speed up.","wrong":{"1":"Citrate <i>inhibits</i> PFK-1 (signalling ample Krebs-cycle intermediates).","2":"NADH inhibits pyruvate dehydrogenase; acetyl-CoA and NADH are negative effectors.","3":"Acetyl-CoA (not ADP) is the allosteric activator of pyruvate carboxylase."}}},{"id":71,"part":"C","unit":14,"blocks":[{"t":"p","h":"The interpretation of any clinical laboratory test is done by comparing the patient's results to the test's reference intervals. For example, the reference interval for white blood cells (WBC) in human adults is 4,500 - 11,000 cells/microlitre. Estimation of this reference interval is done by testing"}],"options":[{"key":"1","text":"a large number of healthy adults and estimating the range between 2.5 to 97.5 percentiles of the reference population."},{"key":"2","text":"a large number of healthy adults and estimating the range between 5 to 95 percentiles of the reference population."},{"key":"3","text":"a large number of random adults and estimating the range between 5 to 95 percentiles of the reference population."},{"key":"4","text":"a large number of random adults and estimating the range between -1.64 and +1.64 standard deviations either side of the mean of the reference population."}],"answer":"1","explanation":{"correct":"A reference interval is defined as the central <b>95%</b> of values in a large sample of <b>healthy (reference) individuals</b>, i.e. the range from the 2.5th to the 97.5th percentile. Option 1 states both requirements correctly.","wrong":{"2":"The 5th–95th percentiles span only the central 90%, not the standard 95%.","3":"The sample must be healthy individuals, not random (unscreened) adults, and 5–95 is the wrong span.","4":"±1.64 SD covers the central 90% (not 95%; that is ±1.96 SD) and uses random, not healthy, subjects."}}},{"id":72,"part":"C","unit":8,"blocks":[{"t":"p","h":"Cystic fibrosis is caused by a recessive allele. Roughly one out of every 500 individuals (0.20%) have this disease. Using the Hardy-Weinberg equation, the percentage of individuals who are carriers of the recessive allele for the disease is"}],"options":[{"key":"1","text":"10.2"},{"key":"2","text":"1.0"},{"key":"3","text":"15.2"},{"key":"4","text":"7.6"}],"answer":"4","explanation":{"correct":"Taking q² = 1/500 = 0.002, q = 0.0447 and p = 0.955. Carrier frequency = 2pq = 2(0.955)(0.0447) ≈ 0.0854, i.e. about 8.5%. The published key is option 4 (7.6%), which corresponds to a disease frequency closer to 1 in 625; with exactly 1 in 500 the nearest intended value is this option.","wrong":{"1":"10.2% corresponds to a higher disease incidence than 1 in 500.","2":"1.0% is far too low for a carrier frequency when q² = 0.002.","3":"15.2% corresponds to a much higher disease incidence."},"notes":["Strict Hardy–Weinberg with q² = 1/500 gives 2pq ≈ 8.5%. The 7.6% key fits q² ≈ 1/625; keep the keyed option for scoring."]}},{"id":73,"part":"C","unit":2,"blocks":[{"t":"p","h":"The Ran GTPase imposes directionality on transport through nuclear pore complexes (NPCs). Like other GTPases, Ran is a molecular switch that can exist in two conformational states, depending on whether bound to GDP or GTP. Possible reasons for compartmentalization of Ran-GTP accumulation are:<br>A. Ran-GAP is enriched in the nucleus<br>B. Ran-GAP is localized in the cytosol<br>C. Ran-GEF is enriched in the nucleus<br>D. The nuclear import receptors help in the compartmentalization of Ran-GTP<br>Which of the options below has all the correct statements about Ran-GTP compartmentalization?"}],"options":[{"key":"1","text":"A only"},{"key":"2","text":"A and B"},{"key":"3","text":"B and C"},{"key":"4","text":"C and D"}],"answer":"3","explanation":{"correct":"Ran-GTP is kept high in the nucleus and low in the cytosol. <b>Ran-GEF (RCC1)</b> is chromatin-bound, so it regenerates Ran-GTP in the nucleus (C). <b>Ran-GAP</b> is cytosolic/at the NPC cytoplasmic face, so it hydrolyses Ran-GTP to GDP as cargo emerges (B). Together B and C create the steep Ran-GTP gradient that drives directional transport.","wrong":{"1":"Ran-GAP is cytosolic, not nuclear, so statement A is wrong.","2":"A (Ran-GAP in the nucleus) is incorrect.","4":"D overstates the import receptors' role; the gradient is set by GEF and GAP localisation, and C alone is incomplete."}}},{"id":74,"part":"C","unit":7,"blocks":[{"t":"p","h":"During physical exercise, a large amount of oxygen is delivered to the active muscles by many physiological adjustments including a change in the P<sub>50</sub> value (which is determined by Po<sub>2</sub> at which hemoglobin is half-saturated with oxygen). The following proposed statements explain the mechanism of change in P<sub>50</sub> during exercise:<br>A. P<sub>50</sub> is increased during exercise as the temperature rises in active muscles.<br>B. During exercise, metabolites accumulate in the active muscles resulting in higher pH that increases P<sub>50</sub>.<br>C. P<sub>50</sub> is increased during exercise as CO<sub>2</sub> is decreased in active muscles.<br>D. An increase in 2,3-DPG has been reported in non-trained person within 60 min of exercise resulting in higher P<sub>50</sub>.<br>Which one of the following options represents the correct combination of the above statements?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"B and C"},{"key":"3","text":"C and D"},{"key":"4","text":"A and D"}],"answer":"4","explanation":{"correct":"A higher P<sub>50</sub> means a right-shifted O<sub>2</sub>-dissociation curve (easier unloading). In exercising muscle this is driven by <b>higher temperature</b> (A) and by <b>raised 2,3-DPG</b> (D). Both correctly raise P<sub>50</sub>.","wrong":{"1":"B is wrong: exercising muscle produces acid (lactate, CO<sub>2</sub>), lowering pH (Bohr effect), not raising it.","2":"B is wrong for the reason above.","3":"C is wrong: active muscle <i>produces</i> CO<sub>2</sub>, and rising CO<sub>2</sub> raises P<sub>50</sub>; it does not decrease."}}},{"id":75,"part":"C","unit":1,"blocks":[{"t":"p","h":"Given below are a few statements regarding the rate of glycolysis, gluconeogenesis and glycogen metabolism.<br>A. Increased blood glucose would decrease gluconeogenesis and increase glycogen synthesis.<br>B. Increased levels of fructose-1,6-bisphosphate inhibits glycolysis.<br>C. Increased blood glucagon inhibits glycogen synthesis and stimulates glycogen break down.<br>D. Increase in AMP levels inhibits glycolysis and stimulates gluconeogenesis.<br>Which one of the following options represents INCORRECT statements?"}],"options":[{"key":"1","text":"A and D"},{"key":"2","text":"B and D"},{"key":"3","text":"A and C"},{"key":"4","text":"B and C"}],"answer":"2","explanation":{"correct":"B is wrong: fructose-1,6-bisphosphate is a feed-forward <i>activator</i> of glycolysis (it activates pyruvate kinase), not an inhibitor. D is wrong: AMP signals low energy, so it <i>stimulates</i> glycolysis (activates PFK-1) and <i>inhibits</i> gluconeogenesis (inhibits FBPase-1). So B and D are the incorrect statements.","wrong":{"1":"A is correct, so A and D is not the pair of incorrect ones.","3":"A and C are both correct statements.","4":"C is correct (glucagon favours glycogen breakdown), so this pair is wrong."}}},{"id":76,"part":"C","unit":10,"blocks":[{"t":"p","h":"In a line transect of length L and half-width w, designed for estimating the density of gaur (D=N/2Lw), N animals were counted. The following statements represent possible assumptions about population sampling.<br>A. The probability of detection is independent of distance from the transect line.<br>B. The animals in question are uniformly distributed through the study area.<br>C. The animals are deemed to be stationary and thus detected only once during the sampling.<br>D. Animals on the line will be detected with a probability equal to 1.<br>Select the options that are considered as assumptions in line transect sampling."}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"C and D"},{"key":"3","text":"A and C"},{"key":"4","text":"B and D"}],"answer":"2","explanation":{"correct":"The simple strip-transect density D = N/(2Lw) assumes every animal within the strip is seen, i.e. detection is certain out to the half-width. Two core assumptions make this valid: animals <b>on the line are detected with probability 1</b> (D), and each animal is <b>counted only once</b> because it is treated as stationary during the survey (C). So the answer is C and D.","wrong":{"1":"A and B: A is false (in distance sampling detection falls with distance; the fixed strip instead assumes certain detection, i.e. D), and B is not required.","3":"A and C: A is false for the reason above, so this pair fails.","4":"B and D: D is a valid assumption, but B (uniform distribution) is not required; random distribution suffices."}}},{"id":77,"part":"C","unit":6,"blocks":[{"t":"p","h":"Biosynthesis of glutamine and asparagine is sensitive to light and to the availability of reduced carbon. Following are a few statements regarding the same.<br>A. Expression of the plastid-localized Glutamine Synthetase (GS) gene is upregulated by light.<br>B. Darkness promotes the expression of Asparagine Synthetase (AS) gene.<br>C. Expression of GS is inhibited by sucrose while that of AS is upregulated by sucrose.<br>D. Asparagine is a more efficient carbon source than glutamine.<br>Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A, B and D"},{"key":"2","text":"B, C and D"},{"key":"3","text":"A, B and C"},{"key":"4","text":"A, C and D"}],"answer":"1","explanation":{"correct":"Glutamine (2 N : 5 C) is carbon-rich and favoured in the light, when reduced carbon is plentiful, so the plastidic <b>GS gene is light-induced</b> (A). Asparagine (2 N : 4 C) is a nitrogen-rich, carbon-economical transport/storage amino acid favoured in the dark, so <b>AS is dark-induced</b> (B) and, as a carbon-sparing N carrier, asparagine is the <b>more efficient long-distance N store</b> relative to glutamine (D). A, B and D are correct.","wrong":{"2":"C is wrong: GS expression is promoted (not inhibited) by sugars/light and AS is repressed by sucrose, the reverse of statement C.","3":"C is incorrect, so this set fails.","4":"C is incorrect, so this set fails."},"notes":["Statement D is best read as asparagine being the more efficient nitrogen-storage/transport compound (high N:C ratio); the published key is option 1."]}},{"id":78,"part":"C","unit":13,"blocks":[{"t":"p","h":"Given below are a few statements on transgenic plants.<br>A. Transgenic plants generated using a transformation vector with the CaMV35S promoter-GUS-35SpA cassette can show variations in expression levels of GUS protein in independent transgenic events due to differences in strength of promoter used to express the GUS gene.<br>B. A transgenic plant containing two insertions of the transgene cassette as inverted repeats in tandem would segregate in a 3:1 ratio for the transgenic phenotype on backcrossing the transgenic plant with the untransformed parent.<br>C. A transgene containing a potential polyadenylation signal in its coding sequence would generate full-length transgene mRNA but a truncated transgenic protein.<br>D. A gene-pyramiding experiment to bring together two transgenic traits by crossing independent homozygous single-copy transgenic lines for each trait would produce a plant homozygous for both the transgenes in the F2 generation.<br>Which one of the following options represents a combination of only correct statements?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"C and D"},{"key":"3","text":"D only"},{"key":"4","text":"A and C"}],"answer":"3","explanation":{"correct":"D is correct: crossing two homozygous single-copy lines gives an F1 heterozygous at both unlinked loci; selfing to F2 yields plants homozygous for both transgenes (1/16). The published key is <b>D only</b>.","wrong":{"1":"A attributes event-to-event variation to 'different promoter strength', but all events use the same CaMV35S promoter; variation comes from position effects and copy number, so A is wrong.","2":"C is wrong: an internal poly(A) signal would truncate the <i>mRNA</i> (premature cleavage/polyadenylation), not leave a full-length mRNA with only a truncated protein.","4":"A and C are both incorrect as stated."},"notes":["The published key is option 3 (D only). Statements A, B and C are each flawed as worded."]}},{"id":79,"part":"C","unit":14,"blocks":[{"t":"p","h":"Given below are a few statements related to enzymes and their functions in molecular reactions.<br>A. Alkaline phosphatases remove 3' phosphates from DNA and RNA.<br>B. S1 nuclease removes single-stranded regions from partially double-stranded DNA.<br>C. 5' end-labelling of DNA molecules can be done by using polynucleotide kinase which transfers a 32P-labelled phosphate group to the 5' end of dephosphorylated DNA.<br>D. 3'-5' exonuclease activity of Taq polymerase releases the reporter from the 3' end of Taqman probes in qPCR.<br>Which one of the following options represents a combination of all correct statements?"}],"options":[{"key":"1","text":"A and D"},{"key":"2","text":"B and C"},{"key":"3","text":"B and D"},{"key":"4","text":"A and C"}],"answer":"2","explanation":{"correct":"B is correct: S1 nuclease is single-strand specific and trims ssDNA/RNA overhangs and loops. C is correct: T4 polynucleotide kinase transfers the γ-<sup>32</sup>P of ATP to a 5′-OH end, the basis of 5′ end-labelling. So B and C.","wrong":{"1":"A is wrong: alkaline phosphatase removes <i>5′</i> phosphates, not 3′.","3":"D is wrong: Taq's probe cleavage in TaqMan assays is its <i>5′→3′</i> exonuclease activity, and Taq lacks 3′→5′ proofreading.","4":"A is wrong (5′, not 3′, phosphates)."}}},{"id":80,"part":"C","unit":9,"blocks":[{"t":"p","h":"Phylogenetic trees are used to examine<br>A. relatedness among different populations, species or genera.<br>B. similarity in characters among different populations, species or genera.<br>C. common ancestry among different populations, species or genera.<br>D. functional significance of traits in populations, species or genera.<br>From the above statements, select the correct combination of statements that best represent the utility of phylogenetic trees."}],"options":[{"key":"1","text":"B, C and D"},{"key":"2","text":"A, B and D"},{"key":"3","text":"A, B and C"},{"key":"4","text":"A, C and D"}],"answer":"3","explanation":{"correct":"Phylogenetic trees depict evolutionary history: they show <b>relatedness</b> (A), <b>shared (homologous) characters</b> used to infer that relatedness (B), and <b>common ancestry</b> (C). A, B and C together capture their purpose.","wrong":{"1":"D (functional significance of traits) is not what a phylogeny establishes; it maps history, not adaptive function.","2":"This set includes D and drops C (common ancestry), a core purpose.","4":"This set includes D and drops B."}}},{"id":81,"part":"C","unit":6,"blocks":[{"t":"p","h":"Following are certain statements regarding Crassulacean Acid Metabolism (CAM) plants:<br>A. The HCO3- concentration is enriched in the cytosol during night by the CO2 coming from the external atmosphere through the open stomata and the mitochondrial respiration.<br>B. Oxaloacetate produced by the action of PEPCase is stored in the vacuole during dark.<br>C. During light, oxaloacetate produces malate that provides CO2 for Calvin-Benson cycle in the chloroplast.<br>D. During dark, phosphoenolpyruvate is produced by the breakdown of starch present in the chloroplast.<br>E. CAM is a mechanism of concentrating CO2 around Rubisco by keeping stomata closed during day.<br>Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A, B and E"},{"key":"2","text":"B, C and E"},{"key":"3","text":"A, C and D"},{"key":"4","text":"A, D and E"}],"answer":"4","explanation":{"correct":"In CAM plants the stomata open at night: atmospheric and respiratory CO<sub>2</sub> gives cytosolic HCO<sub>3</sub><sup>−</sup> (A); PEP, made from nocturnal <b>starch breakdown</b>, is carboxylated by PEPCase and the acid is stored as malate in the vacuole (D); by day, stomata close and decarboxylation releases CO<sub>2</sub> around Rubisco (E). A, D and E are correct.","wrong":{"1":"B is wrong: it is <i>malate</i> (not oxaloacetate) that is stored in the vacuole at night.","2":"B and C misstate what is stored and when malate is decarboxylated.","3":"C is wrong: malate is made at night; by day it is decarboxylated to feed CO<sub>2</sub> to the Calvin cycle."}}},{"id":82,"part":"C","unit":3,"blocks":[{"t":"p","h":"In order to investigate the involvement of the following proteins in the mismatch repair mechanism (MMR), an in vitro reconstitution experiment was performed. A 5'-nicked circular DNA substrate having a C:C mismatch at the PstI site was incubated with different combination of proteins (as shown below), where upon the repair of C:C mismatch, the PstI site will be regenerated. Following the incubation, the resulting DNA were digested with PstI and ScaI restriction endonucleases, and the products were electrophoresed in 0.8% agarose gel."},{"t":"img","src":"data:image/webp;base64,","w":443,"h":523,"alt":"A 5'-nicked circular DNA with a C:C mismatch at a PstI site (1.1 kb and 1.8 kb arcs, with a ScaI site), repaired to regenerate PstI. Below, a +/- table for Polδ, ExoI, Rad27, Msh2-Msh6 across five lanes and an agarose gel at 3.0/2.0/1.0 kb. Lane 1 (all minus): single ~3 kb band (no repair). Lane 2 (Polδ+, ExoI+, Msh2-Msh6+): cut 2.0 + 1.0 kb bands (repaired). Lane 3 (Polδ+, ExoI+, Msh2-Msh6−): only 3 kb (no repair). Lane 4 (Polδ+, Rad27+, Msh2-Msh6+): cut 2.0 + 1.0 kb (repaired). Lane 5 (Polδ+, Msh2-Msh6+, no ExoI, no Rad27): only 3 kb (no repair)"},{"t":"p","h":"Based on the results obtained identify the INCORRECT statement."}],"options":[{"key":"1","text":"Msh2-Msh6 complex is required for the repair of the C:C mismatched DNA."},{"key":"2","text":"Polδ and Msh2-Msh6 complex are necessary for the repair of the C:C mismatched DNA."},{"key":"3","text":"Polδ and Msh2-Msh6 complex are sufficient for the repair of the C:C mismatched DNA."},{"key":"4","text":"ExoI and Rad27 are redundant to each other for the repair of the C:C mismatched DNA."}],"answer":"3","explanation":{"correct":"Repair regenerates the PstI site, so repaired DNA is cut into 2.0 + 1.0 kb fragments while unrepaired DNA stays as one ~3 kb band. The lane with <i>only</i> Polδ + Msh2-Msh6 (no ExoI, no Rad27) shows only the uncut 3 kb band, i.e. <b>no repair</b>. So Polδ + Msh2-Msh6 are necessary but <b>not sufficient</b>, which makes statement 3 the INCORRECT one.","wrong":{"1":"Supported: the lane lacking Msh2-Msh6 (but with Polδ and ExoI) shows no repair, so Msh2-Msh6 is required.","2":"Supported: repair never occurs without both Polδ and Msh2-Msh6.","4":"Supported: ExoI alone (lane 2) or Rad27 alone (lane 4) permits repair, while neither (lane 5) fails, so the two nucleases substitute for each other."}}},{"id":83,"part":"C","unit":1,"blocks":[{"t":"p","h":"Which one of the following options represents a classical Hoogsteen base pairing?"}],"options":[{"key":"1","text":"anti A base-paired with anti T"},{"key":"2","text":"anti G base-paired with anti C"},{"key":"3","text":"syn A base-paired with anti T"},{"key":"4","text":"anti G base-paired with anti U"}],"answer":"3","explanation":{"correct":"A classical Hoogsteen pair uses the purine's N7 and C6 (not the Watson-Crick face), which requires the purine to flip to the <b>syn</b> conformation while the pyrimidine stays anti. <b>syn A : anti T</b> is the standard A·T Hoogsteen pair (as in triplexes and some protein-bound DNA).","wrong":{"1":"anti A : anti T is the standard Watson-Crick pair.","2":"anti G : anti C is Watson-Crick; a G·C Hoogsteen pair needs syn G and a protonated C.","4":"anti G : anti U is a wobble-type pair, not Hoogsteen."}}},{"id":84,"part":"C","unit":4,"blocks":[{"t":"p","h":"SLN1 receptor, a part of a two-component system, is required for osmoregulation in yeast. The yeast mutant (sln1) lacking the SLN1 receptor protein dies. A researcher tries to rescue the mutant by expressing an Arabidopsis gene for the cytokinin receptor, CRE1, which like SLN1 is also a histidine kinase that acts through a two-component system. The following statements are made regarding the outcome of the experiment.<br>A. SLN1 and CRE1 proteins respond to the same external signals and therefore, CRE1 rescues the yeast mutant.<br>B. As CRE1 cannot interact with the downstream signaling pathway in the yeast, it will not rescue the yeast mutant.<br>C. CRE1 will rescue the yeast mutant, only if cytokinin is present.<br>D. The effector domains of CRE1 and SLN1 proteins are sufficiently similar and therefore, CRE1 can induce the downstream signaling pathway and rescue the yeast mutant.<br>Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A and C"},{"key":"2","text":"C and D"},{"key":"3","text":"A only"},{"key":"4","text":"B only"}],"answer":"2","explanation":{"correct":"This is the classic experiment (Inoue et al. 2001) that identified CRE1 as a cytokinin receptor. CRE1's histidine-kinase/effector module is similar enough to SLN1 to feed into the yeast phosphorelay (YPD1→SSK1), so it rescues the sln1 mutant, and this rescue is <b>cytokinin-dependent</b> (C): without cytokinin CRE1 behaves differently. Statements C and D together are correct.","wrong":{"1":"A is wrong: the two receptors respond to different ligands (osmolarity vs cytokinin); the rescue works despite different external signals, via the shared phosphorelay.","3":"A alone is incorrect.","4":"B is wrong: CRE1 <i>can</i> engage the yeast downstream pathway, which is why rescue occurs."}}},{"id":85,"part":"C","unit":10,"blocks":[{"t":"p","h":"A student used the mark-recapture method to assess the population size of grasshopper in a field. The student was asked to repeat the recapture procedure once on three consecutive days. The procedure followed by the student and the observations made are as follows:<br>A. On day one, 40 grasshoppers were captured, marked and released back in the field.<br>B. On day two, 60 grasshoppers were re-captured of which, 4 were marked. He marked the unmarked ones and released all 60 in the field.<br>C. On day three, 50 grasshoppers were re-captured of which 7 were marked. He marked the unmarked ones and released all 50 in the field.<br>D. On day four, 25 grasshoppers were re-captured of which 6 were marked.<br>The student was asked to calculate the population size based on the mean of the three observations. The estimated population size is:"}],"options":[{"key":"1","text":"600"},{"key":"2","text":"~622"},{"key":"3","text":"~351"},{"key":"4","text":"~454"}],"answer":"2","explanation":{"correct":"Lincoln-Petersen: N = (marked in population × total caught) / recaptured marked. Day 2: 40×60/4 = 600. Day 3: marked-at-large = 40 + 56 = 96; N = 96×50/7 ≈ 686. Day 4: marked-at-large = 96 + 43 = 139; N = 139×25/6 ≈ 579. Mean ≈ (600 + 686 + 579)/3 ≈ <b>622</b>.","wrong":{"1":"600 is only the first estimate, not the mean of the three.","3":"~351 underestimates; it does not match the Lincoln-Petersen means.","4":"~454 does not match the computed mean."}}},{"id":86,"part":"C","unit":5,"blocks":[{"t":"p","h":"The following statements have been made regarding cell specification in an early embryo:<br>A. The entire embryo rarely interacts with its environment, and its developmental trajectory cannot be guided by its immediate \"ecosystem\".<br>B. When cells are removed, changes in cellular biochemistry and function are never preceded by a process involving the commitment of the cell to a certain fate.<br>C. The fate of a cell or a tissue in the intact embryo is said to be specified when it is not capable of differentiating autonomously on being placed in a neutral environment, such as a petri dish or test tube.<br>D. If cells are removed, the interactions of the remaining cells compensate the fate of the removed cells, because the fate of a cell depends upon the conditions in which the cell finds itself."},{"t":"img","src":"data:image/webp;base64,","w":741,"h":158,"alt":"An experiment: a glass needle removes cells from an early blastula; the remaining cells still develop into a normal larval (tadpole-like) form"},{"t":"p","h":"With regard to the experiment shown below, where removal of cells from an early blastula leads to normal development of the larval form, which one of the above combination of statements apply to the development of the organism?"}],"options":[{"key":"1","text":"A and D"},{"key":"2","text":"Only D"},{"key":"3","text":"B and C"},{"key":"4","text":"Only C"}],"answer":"2","explanation":{"correct":"Removing cells yet still obtaining a normal larva is the signature of <b>regulative (conditional) development</b>: the remaining cells sense the altered context and adjust their fates to replace what was lost. Statement D captures exactly this, that a cell's fate depends on its surroundings, so the answer is <b>Only D</b>.","wrong":{"1":"A is wrong: regulative development shows the embryo <i>does</i> respond to its cellular environment.","3":"B denies fate commitment and C describes conditional specification backwards; neither fits.","4":"C is mis-stated (it inverts the definition of specification), so it does not apply."}}},{"id":87,"part":"C","unit":6,"blocks":[{"t":"p","h":"Sucrose-phosphate synthase (SPS) is a key enzyme in the biosynthesis of sucrose in plants. Following are certain statements regarding SPS:<br>A. Uridine-diphosphate glucose and fructose-6-phosphate are the substrates for SPS.<br>B. SPS directly converts its substrate into sucrose.<br>C. Phosphorylation activates while dephosphorylation inactivates SPS.<br>D. SPS converts its substrate into sucrose-6-phosphate which is then converted to sucrose by the action of sucrose-phosphate phosphatase.<br>E. Glucose 6-phosphate activates while Pi inactivates SPS.<br>Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A, C and D"},{"key":"2","text":"A, B and E"},{"key":"3","text":"B, C and D"},{"key":"4","text":"A, D and E"}],"answer":"4","explanation":{"correct":"SPS joins <b>UDP-glucose + fructose-6-phosphate</b> (A) to make <b>sucrose-6-phosphate</b>, which sucrose-phosphate phosphatase then dephosphorylates to sucrose (D). SPS is allosterically <b>activated by glucose-6-phosphate and inhibited by Pi</b> (E). A, D and E are correct.","wrong":{"1":"C is wrong: SPS is activated by <i>dephosphorylation</i> and inhibited by phosphorylation, the opposite of statement C.","2":"B is wrong: the direct product is sucrose-6-phosphate, not sucrose.","3":"B and C are both incorrect."}}},{"id":88,"part":"C","unit":7,"blocks":[{"t":"p","h":"Given below are the blood clotting factors in column X and their names in column Y.<br>Column X: a. XII, b. HMWK, c. Pre-Ka, d. X<br>Column Y: i. Fitzgerald factor, ii. Laki-Lorand factor, iii. Stuart-Prower factor, iv. Fletcher factor<br>Which of the following combination is a correct match of the factor with its name."}],"options":[{"key":"1","text":"a-iv, b-iii, c-i, d-ii"},{"key":"2","text":"a-ii, b-iii, c-i, d-iv"},{"key":"3","text":"a-ii, b-i, c-iv, d-iii"},{"key":"4","text":"a-i, b-ii, c-iv, d-iii"}],"answer":"3","explanation":{"correct":"Standard eponyms: HMWK = Fitzgerald factor (b-i); prekallikrein = Fletcher factor (c-iv); factor X = Stuart-Prower factor (d-iii). The keyed answer is option 3, a-ii, b-i, c-iv, d-iii.","wrong":{"1":"Misassigns HMWK and prekallikrein.","2":"Misassigns the Fitzgerald/Fletcher/Stuart-Prower eponyms.","4":"a-i pairs factor XII with Fitzgerald, which belongs to HMWK."},"notes":["The Laki-Lorand factor is factor XIII (fibrin-stabilising), not factor XII as listed in column X, so item 'a' is almost certainly a typo for XIII. The published key is option 3 (a-ii, b-i, c-iv, d-iii)."]}},{"id":89,"part":"C","unit":2,"blocks":[{"t":"p","h":"In vivo interaction between FLAG-tagged protein P and chaperone H was examined by co-immunoprecipitation (co-IP). Co-chaperone A was included and the co-IP was performed in the presence or absence of cycloheximide (CHX). The results of the co-IP experiments are shown below."},{"t":"img","src":"data:image/webp;base64,","w":504,"h":606,"alt":"A +/- table across five lanes for FLAG-P, Chaperone H, Co-chaperone A, CHX, with anti-FLAG IP blots and whole-cell-lysate blots. In the IP:FLAG panel: FLAG-P is pulled down in lanes 2-5. Chaperone H co-precipitates with FLAG-P in lane 3 (H+, A−) and lane 4 (all present) but NOT in lane 5 (CHX+). Co-chaperone A co-precipitates with FLAG-P only in lane 4 (H+, A+), not in lane 2 (H−, A+)"},{"t":"p","h":"Which of the following interpretations from these experiments is INCORRECT?"}],"options":[{"key":"1","text":"Protein P interacts with chaperone H and co-chaperone A."},{"key":"2","text":"Chaperone H interacts only with the newly synthesized protein P."},{"key":"3","text":"Interaction between co-chaperone A and protein P is independent of chaperone H."},{"key":"4","text":"Interaction between chaperone H and protein P is independent of co-chaperone A."}],"answer":"3","explanation":{"correct":"Co-chaperone A co-IPs with P only in the lane where chaperone H is also present (lane 4); when H is absent (lane 2), A does <i>not</i> pull down with P. So the A-P interaction <b>requires</b> chaperone H, which makes statement 3 (A-P interaction is independent of H) the INCORRECT interpretation.","wrong":{"1":"Supported: P co-precipitates chaperone H (lanes 3, 4) and co-chaperone A (lane 4).","2":"Supported: with CHX (lane 5) no new P is made and H no longer co-IPs with P, so H binds only newly synthesised P.","4":"Supported: in lane 3 (co-chaperone A absent) chaperone H still co-IPs with P, so H-P binding does not need A."}}},{"id":90,"part":"C","unit":5,"blocks":[{"t":"p","h":"Overexpression of protein 'A' in the brain of Drosophila melanogaster causes the degradation of ovaries in the animal. Overexpression of a secretion-incompetent allele of 'A' does not cause this phenotype. However, downregulation of protein 'B' in ovaries concomitant with overexpression of protein 'A' in the brain prevents ovary degradation. 'A' and 'B' are found to physically interact in ovary lysates. In the light of the above experiments, which of the following inferences would be correct?"}],"options":[{"key":"1","text":"The protein 'A' cell autonomously influences ovary development while B is secreted to influence brain function."},{"key":"2","text":"'A' is a ligand secreted from the brain and 'B' is a receptor in ovaries."},{"key":"3","text":"'A' is a neurotransmitter secreted from the brain and 'B' is a signal transducer in the ovaries."},{"key":"4","text":"'A' is a receptor secreted from the ovaries and 'B' is a ligand in the ovary cell membrane."}],"answer":"2","explanation":{"correct":"A must be <i>secreted</i> from the brain to act (a secretion-incompetent A has no effect), so A is a brain-derived signalling ligand that travels to the ovary. B is needed in the ovary for the effect and physically binds A, so B is the ovarian <b>receptor</b>. Thus A = secreted ligand, B = ovarian receptor.","wrong":{"1":"A acts non-autonomously (brain → ovary), and B is not shown to act on the brain.","3":"A classic neurotransmitter acts across a synapse, not as a long-range ovary-degrading signal, and B is a receptor, not merely a downstream transducer.","4":"A is from the brain, not secreted from the ovaries; the receptor is B."}}},{"id":91,"part":"C","unit":6,"blocks":[{"t":"p","h":"In the classic ABCDE model of flower development, different combinations of ABCDE class genes result in different whorls of organs. Which one of the following models would likely give rise to unisexual flower structures?"},{"t":"img","src":"data:image/webp;base64,","w":730,"h":561,"alt":"Four ABCDE-model diagrams, each a row of four whorls over an E domain. Option 1: A+B / A+B+C / B+C / C arrangement for the two shown flowers. The models differ in which whorls carry stamen-specifying (B+C) versus carpel-specifying (C) combinations"}],"options":[{"key":"1","text":"Model 1"},{"key":"2","text":"Model 2"},{"key":"3","text":"Model 3"},{"key":"4","text":"Model 4"}],"answer":"2","explanation":{"correct":"In the ABCDE (floral quartet) model, petals = A+B+E, stamens = B+C+E, carpels = C+E. A unisexual flower forms when one of the reproductive organ identities is missing, so a plant making a flower with stamens but no carpels (or carpels but no stamens) is unisexual. The keyed model (option 2) shows a whorl combination that produces only one sex's reproductive organ.","wrong":{"1":"Model 1 specifies both stamens and carpels, giving a bisexual flower.","3":"Model 3 retains both reproductive identities.","4":"Model 4 retains both reproductive identities."},"notes":["The figure's whorl combinations are hard to read from the scan; the published key is option 2."]}},{"id":92,"part":"C","unit":10,"blocks":[{"t":"p","h":"An ecological community is more than just the sum of the attributes of the constituent species. Which one of the following options is NOT an attribute of ecological communities?"}],"options":[{"key":"1","text":"Local extinction of a species caused by demographic stochasticity."},{"key":"2","text":"Logseries species abundance distributions."},{"key":"3","text":"Stability of a food web in the face of disturbance."},{"key":"4","text":"The limits to similarity of competing species."}],"answer":"1","explanation":{"correct":"Demographic stochasticity acting on a single species' local extinction is a <b>population-level</b> property, not an emergent community attribute. The other three, species-abundance distributions, food-web stability and limiting similarity, are genuine properties of the community as a whole.","wrong":{"2":"Species-abundance distributions (e.g. log-series) are community-level patterns.","3":"Food-web stability is an emergent community property.","4":"Limiting similarity of coexisting competitors is a community assembly property."}}},{"id":93,"part":"C","unit":3,"blocks":[{"t":"p","h":"Some features mentioned below are important for the segregation of homologous chromosomes in meiosis I.<br>A. Synaptonemal complex formation between homologous chromosomes.<br>B. Degradation of cohesins at the chromosome arms.<br>C. Retention of cohesins at the centromeres.<br>D. Bi-orientation of kinetochores of sister chromatids.<br>Which one of the following options has all correct features?"}],"options":[{"key":"1","text":"A and B only"},{"key":"2","text":"A and C only"},{"key":"3","text":"A, B and C only"},{"key":"4","text":"A, B, C and D"}],"answer":"3","explanation":{"correct":"Proper meiosis I segregation needs the synaptonemal complex to pair homologues and enable crossovers (A), cleavage of <b>arm cohesin</b> to resolve chiasmata and let homologues separate (B), and protection of <b>centromeric cohesin</b> (by shugoshin) so sisters stay together until meiosis II (C). Sister kinetochores are <i>mono</i>-oriented (co-oriented) in meiosis I, not bi-oriented, so D is wrong. A, B and C only.","wrong":{"1":"Omits C (centromeric cohesin protection), which is essential.","2":"Omits B (arm cohesin removal), needed to separate homologues.","4":"D is wrong: meiosis I needs mono-orientation of sister kinetochores, not bi-orientation."}}},{"id":94,"part":"C","unit":7,"blocks":[{"t":"p","h":"The following statements are made for the effect of hormones on the glomerular filtration rate (GFR).<br>A. Norepinephrine, epinephrine, and endothelin constrict renal blood vessels and decrease GFR.<br>B. Endothelin dilates renal blood vessels to increase GFR.<br>C. Norepinephrine and endothelin constrict renal blood vessels and decrease GFR, while epinephrine dilates renal blood vessels to increase GFR.<br>D. Prostaglandin (PGE2) and bradykinin decrease renal vascular resistance and increase GFR.<br>Which one of the following options represents the combination of correct statements?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"B and C"},{"key":"3","text":"C and D"},{"key":"4","text":"A and D"}],"answer":"4","explanation":{"correct":"Vasoconstrictors, <b>norepinephrine, epinephrine and endothelin</b>, raise renal vascular resistance and lower GFR (A). Vasodilators such as <b>PGE<sub>2</sub> and bradykinin</b> reduce renal vascular resistance and raise (or protect) GFR (D). So A and D.","wrong":{"1":"B is wrong: endothelin is a vasoconstrictor that lowers GFR, not a dilator.","2":"B and C both mis-state endothelin/epinephrine as dilators.","3":"C wrongly calls epinephrine a renal vasodilator."}}},{"id":95,"part":"C","unit":5,"blocks":[{"t":"p","h":"In a hypothetical organism, at a four-celled embryonic stage, blastomere 'X' instructs one of the daughter cells of an adjoining blastomere 'Y' to take the fate 'Ya'. The other daughter cell takes the fate 'Yp'. This is illustrated in the figure below as lineages for Ya and Yp. If the X blastomere is removed, both daughter cells take up the Yp fate."},{"t":"img","src":"data:image/webp;base64,","w":494,"h":310,"alt":"Normal development: blastomere X next to Y; Y divides into one Ya and one Yp daughter. In the absence of blastomere X: Y divides into two Yp daughters. The instruction is a paracrine factor Pap2 secreted by X acting on Pap5 on the membrane of Y"},{"t":"p","h":"This instruction is mediated by a paracrine factor, Pap2 secreted by X blastomere interacting with Pap5 present on the membrane of Y blastomere. The following experimental manipulations were carried out, which involved creating partial genetically mosaic embryos in vitro and following the fate of the Y blastomere. Which one of the mosaics will show a developmental pattern similar to that when blastomere X is removed?"}],"options":[{"key":"1","text":"X blastomere null for Pap2 and wild type Y blastomere"},{"key":"2","text":"Wild type X blastomere and constitutively activated Pap5 Y blastomere"},{"key":"3","text":"X blastomere null for Pap2 and constitutively activated Pap5 Y blastomere"},{"key":"4","text":"X blastomere null for Pap5 and wild type Y blastomere"}],"answer":"1","explanation":{"correct":"Removing X removes the Pap2 signal, so Y gets no induction and makes two Yp cells. The equivalent mosaic is one where the Pap2 signal is absent but Y can still respond: an <b>X blastomere null for Pap2 with a wild-type Y</b>. With no ligand, Pap5 on Y is never activated, exactly mimicking the loss of X.","wrong":{"2":"Constitutively active Pap5 signals without X, giving the <i>opposite</i> (Ya) outcome, not the X-removed phenotype.","3":"Constitutively active Pap5 drives signalling regardless of missing Pap2, so it does not mimic X removal.","4":"A Pap5-null Y cannot respond even when X is present; this differs from simply removing X (here Y lacks the receptor, a distinct lesion), and the cleanest phenocopy of 'X removed' is loss of the ligand with a wild-type Y."}}},{"id":96,"part":"C","unit":2,"blocks":[{"t":"p","h":"The CDS of the shortest isoform of human gene 'A' is cloned into a 3.3 kb vector under a CMV promoter at the BamHI and XhoI sites (pCMV-A vector)."},{"t":"img","src":"data:image/webp;base64,","w":782,"h":488,"alt":"Left, an agarose gel of pCMV-A digested with XhoI and BamHI releasing a small insert; a ladder from 8000 to 250 bp. Right, an anti-A Western blot on A-null HeLa lysate: lane 1 transfected with pCMV-A, lane 2 untransfected. Lane 1 shows a regularly spaced ladder of bands between about 53 and 90 kDa (each step ~8.5 kDa apart) together with a low-molecular-weight smear near 9-30 kDa; lane 2 is blank"},{"t":"p","h":"From the agarose gel and SDS-PAGE images shown above, which one of the following is most likely true for protein A in HeLa cells:"}],"options":[{"key":"1","text":"Protein A forms homo-multimers."},{"key":"2","text":"Protein A is degraded by the lysosome."},{"key":"3","text":"Protein A is polyubiquitinated."},{"key":"4","text":"Protein A localizes to autophagosomes."}],"answer":"3","explanation":{"correct":"The transfected lane shows a regular ladder of bands separated by about <b>8.5 kDa</b>, the mass of a single ubiquitin, together with a high-density smear. A ladder whose rungs step by one ubiquitin is the classic signature of <b>polyubiquitination</b> of protein A.","wrong":{"1":"Homo-multimers would step by the whole monomer mass, not by the ~8.5 kDa ubiquitin increment seen here.","2":"Lysosomal degradation yields heterogeneous smaller fragments, not a regular 8.5 kDa ladder.","4":"Autophagosome localisation concerns trafficking and would not produce a ubiquitin ladder on SDS-PAGE."}}},{"id":97,"part":"C","unit":13,"blocks":[{"t":"p","h":"A researcher used CRISPR-Cas9 system and observed a different type of mutation in two alleles of a target gene in a T0 transgenic plant. These mutations are designated as follows:<br>Allele 1: addition of a nucleotide<br>Allele 2: deletion of a nucleotide<br>The observed mutations can be classified as"}],"options":[{"key":"1","text":"monoallelic mutations."},{"key":"2","text":"biallelic heterozygous mutations."},{"key":"3","text":"biallelic homozygous mutations."},{"key":"4","text":"chimeric mutations."}],"answer":"2","explanation":{"correct":"Both alleles of the gene are edited, but each carries a <i>different</i> indel (one insertion, one deletion). Editing of both alleles makes it biallelic, and the two differing edits make it <b>biallelic heterozygous</b>.","wrong":{"1":"Monoallelic would mean only one allele was edited.","3":"Biallelic homozygous would require both alleles to carry the <i>same</i> edit.","4":"Chimeric refers to a mix of genotypes among cells of the plant, not two defined edited alleles."}}},{"id":98,"part":"C","unit":7,"blocks":[{"t":"p","h":"Which one of the following options represents all correct matches between Column X and Column Y?<br>Column X: Microorganism — A. Influenza virus, B. Entamoeba histolytica, C. Streptococcus pyogenes, D. Human immunodeficiency virus<br>Column Y: Host receptor — i. N-acetylglucosamine, ii. CD44, iii. Sialic acid residues of glycoproteins and glycolipids, iv. CD4"}],"options":[{"key":"1","text":"A-i, B-ii, C-iii, D-iv"},{"key":"2","text":"A-ii, B-iv, C-i, D-iii"},{"key":"3","text":"A-iv, B-ii, C-iii, D-i"},{"key":"4","text":"A-iii, B-ii, C-i, D-iv"}],"answer":"4","explanation":{"correct":"Influenza haemagglutinin binds <b>sialic acid</b> (A-iii). <i>Entamoeba histolytica</i> uses the Gal/GalNAc lectin and adheres via <b>CD44</b>-type/hyaluronan interactions (B-ii). <i>Streptococcus pyogenes</i> binds <b>N-acetylglucosamine</b>-containing host glycans (C-i). HIV gp120 binds <b>CD4</b> (D-iv). So A-iii, B-ii, C-i, D-iv.","wrong":{"1":"Influenza binds sialic acid, not GlcNAc, so A-i is wrong.","2":"Assigns CD4 to Streptococcus and sialic acid to HIV, both wrong.","3":"Assigns GlcNAc to Streptococcus correctly but puts sialic acid on influenza as A-iv incorrectly."}}},{"id":99,"part":"C","unit":8,"blocks":[{"t":"p","h":"Given below are a few statements on concepts of molecular breeding.<br>A. Correlations between quantitative traits can be because of pleiotropic effects of the same gene and/or genetic linkage of genes associated with the traits.<br>B. In a Recombinant Inbred Line (RIL) population, genetic segregation of both dominant and codominant markers occurs in a 1:1 ratio.<br>C. Near isogenic lines (NILs) can be produced by repeated backcrossing of the F1 to a recurrent parent.<br>D. SNPs are dominant markers.<br>Which one of the following options represents all correct statements?"}],"options":[{"key":"1","text":"A and B only"},{"key":"2","text":"A, B and D"},{"key":"3","text":"A, B and C"},{"key":"4","text":"C and D only"}],"answer":"3","explanation":{"correct":"A is correct: trait correlations arise from pleiotropy or linkage. B is correct: in RILs (nearly all homozygous) each locus segregates ~1:1 between the two parental alleles, for both dominant and codominant markers. C is correct: repeated backcrossing to a recurrent parent, with selection, builds near-isogenic lines. So A, B and C.","wrong":{"1":"Omits C, which is a correct statement.","2":"D is wrong: SNPs are <i>codominant</i> markers (both alleles are detectable in a heterozygote).","4":"D is wrong, so this set fails."}}},{"id":100,"part":"C","unit":6,"blocks":[{"t":"p","h":"ABA plays an important role in plant response to water stress. In the table below, column X represents some of the important enzymes in ABA biosynthesis/degradation pathways, while column Y summarizes the major function of these enzymes.<br>Column X: A. 9-cis-epoxycarotenoid dioxygenase, B. Cytochrome P450 monooxygenase CYP707A3, C. ABA glucosyltransferase, D. β-glucosidase<br>Column Y: i. Involved in the oxidative ABA catabolism, ii. Production of a sugar-conjugated form of ABA, iii. Xanthoxin production, iv. Releases ABA from its sugar-conjugated form<br>Choose the option showing the correct match between column X and column Y?"}],"options":[{"key":"1","text":"A-iv, B-ii, C-i, D-iii"},{"key":"2","text":"A-iii, B-i, C-ii, D-iv"},{"key":"3","text":"A-ii, B-iii, C-iv, D-i"},{"key":"4","text":"A-i, B-iv, C-iii, D-ii"}],"answer":"2","explanation":{"correct":"<b>NCED</b> cleaves a carotenoid to xanthoxin, the rate-limiting biosynthetic step (A-iii). <b>CYP707A</b> is the 8′-hydroxylase of oxidative ABA catabolism (B-i). <b>ABA glucosyltransferase</b> makes ABA-glucose ester, a conjugated store (C-ii). <b>β-glucosidase</b> hydrolyses ABA-GE to release free ABA (D-iv). So A-iii, B-i, C-ii, D-iv.","wrong":{"1":"Assigns NCED to the sugar-releasing step, which is β-glucosidase.","3":"Scrambles the biosynthetic and catabolic roles.","4":"Assigns NCED to oxidative catabolism, which is CYP707A's role."}}},{"id":101,"part":"C","unit":10,"blocks":[{"t":"p","h":"The following statements represent possible outcomes of competition between two species.<br>A. Niche differentiation between species<br>B. Expansion of fundamental niche of both species<br>C. Expansion of realized niche of both species<br>D. Character displacement between species<br>Which one of the following options represents the correct set of possible outcomes?"}],"options":[{"key":"1","text":"A and C"},{"key":"2","text":"B and D"},{"key":"3","text":"A and D"},{"key":"4","text":"A and B"}],"answer":"3","explanation":{"correct":"Interspecific competition leads to <b>niche differentiation</b> (resource partitioning, A) and, over evolutionary time, to <b>character displacement</b> (divergence of competing species' traits where they co-occur, D). Both reduce competition. So A and D.","wrong":{"1":"C is wrong: competition <i>contracts</i> the realized niche (it is the fundamental niche minus competitive exclusion), not expands it.","2":"The fundamental niche is intrinsic and not expanded by competition; B is wrong.","4":"B is incorrect, so this set fails."}}},{"id":102,"part":"C","unit":1,"blocks":[{"t":"p","h":"Given below are four topology diagrams corresponding to different proteins. N and C denote the N- and C-terminal ends of the protein chains."},{"t":"img","src":"data:image/webp;base64,","w":736,"h":610,"alt":"Four four-stranded antiparallel β-sheet topology diagrams. A: N/C at the bottom, the chain crosses from strand 1 over the top to strand 4 and works back (1-4-3-2 Greek-key-type connectivity). C: the same connectivity drawn upside-down with N/C at the top. B: N/C at the bottom, a simple sequential up-down meander (1-2-3-4). D: N/C at the top, a connectivity distinct from A/C"},{"t":"p","h":"Which one of the following statements is CORRECT?"}],"options":[{"key":"1","text":"All four are of different folds."},{"key":"2","text":"All four are of the same fold."},{"key":"3","text":"(A), (C) and (D) are of the same fold."},{"key":"4","text":"(A) and (C) are of the same fold."}],"answer":"4","explanation":{"correct":"A fold is defined by the strand order and loop connectivity, independent of how the diagram is oriented on the page. <b>A and C share the same connectivity</b>: C is simply A rotated 180° (N/C at the top instead of the bottom), so they are the same fold. B is a plain sequential β-meander and D has a different connectivity, so neither matches A/C.","wrong":{"1":"A and C are the same fold, so not all four differ.","2":"B (a simple meander) and D do not share A/C's connectivity, so not all four are the same.","3":"D does not share the A/C connectivity, so grouping D with A and C is wrong."},"notes":["The published key is option 4. A and C are the same topology drawn in opposite orientations; the judgement rests on the strand connectivity read from the scanned diagrams."]}},{"id":103,"part":"C","unit":9,"blocks":[{"t":"p","h":"The following statements describe different patterns of sequence evolution.<br>A. Most non-synonymous mutations are selected against.<br>B. Synonymous mutations can accumulate.<br>C. The ratio of non-synonymous to synonymous substitutions is high.<br>D. Non-synonymous sites accumulate mutations at higher rates.<br>Which one of the options is NOT true about sequence evolution under purifying selection?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"C and D"},{"key":"3","text":"A and C"},{"key":"4","text":"B and D"}],"answer":"2","explanation":{"correct":"Under purifying (negative) selection, deleterious non-synonymous changes are removed, so dN is low while synonymous (dS) changes accumulate neutrally, giving dN/dS &lt; 1. Thus A and B are <i>true</i> of purifying selection, whereas <b>C (high dN/dS) and D (non-synonymous sites evolving faster) are NOT true</b>, they describe positive selection. The question asks which are not true, so C and D.","wrong":{"1":"A and B are both true under purifying selection.","3":"A is true; only C is false in this pair.","4":"B is true; only D is false in this pair."}}},{"id":104,"part":"C","unit":9,"blocks":[{"t":"p","h":"Molecular phylogeny indicates that whales are closely related to the artiodactyls. Given this information, select the phylogenetic tree that shows the correct set of terrestrial animals with which modern whales share their most recent ancestry."},{"t":"img","src":"data:image/webp;base64,","w":549,"h":372,"alt":"Four candidate trees. 1: (Pigs, Whale, Camel, Horse). 2: (Pigs, Horse, Whale, Hippo). 3: (Pigs, Whale, Hippo, Horse) with whale and hippo as closest. 4: (Hippo, Pigs, Whale, Camel). The correct tree pairs whale most closely with hippopotamus"}],"options":[{"key":"1","text":"Tree 1"},{"key":"2","text":"Tree 2"},{"key":"3","text":"Tree 3"},{"key":"4","text":"Tree 4"}],"answer":"3","explanation":{"correct":"Molecular data place whales (Cetacea) as the sister group of hippopotamuses within Artiodactyla (the clade Cetartiodactyla / Whippomorpha). The correct tree is the one where <b>whale and hippo are each other's closest relatives</b>, with pigs, camels and horses more distant. That is tree 3.","wrong":{"1":"Pairs whale with camel, not hippo.","2":"Does not place hippo as the whale's closest relative in the right topology.","4":"Groups hippo with pigs rather than as the whale's sister."}}},{"id":105,"part":"C","unit":8,"blocks":[{"t":"p","h":"In a frog species, foot webbing is controlled by a single gene where the allele for nonwebbed feet (W) is dominant and webbed feet (w) is recessive. Assume there is a population of 500 individuals, where 320 have the genotype WW, 160 have the heterozygous genotype of Ww, and 20 have the genotype ww. What are the frequencies of the three genotypes and alleles in this population?"}],"options":[{"key":"1","text":"Genotype frequencies: 0.04 WW, 0.32 Ww and 0.64 ww; Allele frequencies W = 0.5 and w = 0.5"},{"key":"2","text":"Genotype frequencies: 0.32 WW, 0.64 Ww and 0.04 ww; Allele frequencies W = 0.8 and w = 0.2"},{"key":"3","text":"Genotype frequencies: 0.64 WW, 0.32 Ww and 0.04 ww; Allele frequencies W = 0.8 and w = 0.2"},{"key":"4","text":"Genotype frequencies: 0.34 WW, 0.34 Ww and 0.32 ww; Allele frequencies W = 0.5 and w = 0.5"}],"answer":"3","explanation":{"correct":"Genotype frequencies: WW = 320/500 = 0.64, Ww = 160/500 = 0.32, ww = 20/500 = 0.04. Allele W = 0.64 + ½(0.32) = 0.80; w = 0.04 + ½(0.32) = 0.20. So option 3.","wrong":{"1":"Inverts the WW and ww frequencies.","2":"Gives the right allele frequencies but wrong genotype frequencies (0.32/0.64 swapped).","4":"Incorrect counts and allele frequencies."}}},{"id":106,"part":"C","unit":8,"blocks":[{"t":"p","h":"A cancer clinic is treating four unrelated patients suffering from chronic myelogenous leukemia. A researcher sequences the Philadelphia chromosome from the leukemic cells of these patients and makes the following statements:<br>A. The DNA sequence was identical in the translocation breakage and rejoining (TBR) sections in all leukemic cells in all 4 patients.<br>B. The DNA sequence was identical in all leukemic cells from patient 1, but every patient had a different TBR sequence.<br>C. All patients have translocations between long arms of chromosomes 9 and 22.<br>D. All patients have translocations between long arm of chromosome 9 and short arm of chromosome 22.<br>Which one of the following options represents a combination of all correct statements?"}],"options":[{"key":"1","text":"A and D"},{"key":"2","text":"B and C"},{"key":"3","text":"B and D"},{"key":"4","text":"A and C"}],"answer":"2","explanation":{"correct":"The Philadelphia chromosome is t(9;22)(q34;q11), a fusion of the <b>long arms (q)</b> of chromosomes 9 and 22, forming BCR-ABL1 (C). Within one patient the leukaemia is clonal, so all cells share the same breakpoint, but the exact breakpoint differs between unrelated patients, so <b>each patient has a different TBR sequence</b> (B). B and C.","wrong":{"1":"A is wrong: breakpoints vary between patients, so the TBR sequence is not identical across all four.","3":"D is wrong: the translocation joins the long arm of 22 (q11), not the short arm.","4":"A is wrong for the breakpoint-variation reason above."}}},{"id":107,"part":"C","unit":3,"blocks":[{"t":"p","h":"URA3 gene expression allows yeast cells to grow on synthetic media lacking Uracil (SC-URA). Shown below are cell types having URA3 gene inserted at distinct positions of the chromosome. The ability of each cell type to grow on SC-URA in either log or stationary phase is listed on the right."},{"t":"img","src":"data:image/webp;base64,","w":900,"h":231,"alt":"Three cell types, each a chromosome with URA3 placed at a different position (near the telomere for types 2 and 3, internal for type 1). Growth on SC-URA: Cell Type 1 grows in both log and stationary phase (+/+); Cell Type 2 grows in log but not stationary (+/-); Cell Type 3 grows in stationary but not log (-/+)"},{"t":"p","h":"The following interpretations were made:<br>A. URA3 gene in cell type 1 is probably located in a heterochromatic region.<br>B. URA3 gene in cell type 2 is located in facultative heterochromatin.<br>C. URA3 gene in cell type 2 is probably located in a chromosome region silenced in log phase.<br>D. URA3 gene in cell type 3 is heterochromatinized in log phase.<br>Which one of the following options are correct interpretations?"}],"options":[{"key":"1","text":"A and C"},{"key":"2","text":"B and D"},{"key":"3","text":"A and D"},{"key":"4","text":"B and C"}],"answer":"2","explanation":{"correct":"Cell type 3 grows only in stationary phase, so its URA3 is silenced (heterochromatinised) in <b>log phase</b> and de-repressed later (D). Cell type 2 grows only in log phase, so its URA3 is <b>facultative heterochromatin</b> that becomes silenced in stationary phase (B). B and D.","wrong":{"1":"A is wrong: cell type 1 grows in both phases, so its URA3 is in open euchromatin, not heterochromatin; and C mis-states type 2 (it is silenced in stationary, not log, phase).","3":"A is incorrect (type 1 is not heterochromatic).","4":"C wrongly says type 2 is silenced in log phase, when it actually grows in log phase."}}},{"id":108,"part":"C","unit":3,"blocks":[{"t":"p","h":"A complete retroposon was cloned under the entire galactose inducible promoter. The construct, as shown below, was inserted in the yeast genome to study the transposition event."},{"t":"img","src":"data:image/webp;base64,","w":455,"h":101,"alt":"A construct: GAL promoter driving a 'Novel Element' (a complete retrotransposon), integrated into the yeast genome"},{"t":"p","h":"Some of the predicted outcomes are listed below:<br>A. Cells grown in presence of glucose or galactose lead to increase in copy number of the transposon.<br>B. The transposed copies will be same as the construct inserted in the genome.<br>C. The transposed copies cannot transpose further.<br>D. The transposed copies will not respond to either glucose or galactose in the media.<br>Assuming that the hypothesis is correct, choose the option that has all likely outcomes."}],"options":[{"key":"1","text":"A and B only"},{"key":"2","text":"A and C only"},{"key":"3","text":"A, B and C"},{"key":"4","text":"D only"}],"answer":"4","explanation":{"correct":"A retroposon (Ty-like element) transposes through an RNA intermediate. Transcription starts at the element's own internal promoter, not the GAL promoter, so the new copies lack the upstream GAL promoter and are flanked only by the element's LTRs. Therefore the transposed copies <b>differ from the integrated construct</b> (they are not GAL-driven, so B is wrong) and, having their own LTR promoters, they <b>can still transpose</b> (C is wrong) and <b>do not respond to glucose/galactose</b> (D is correct). Only D is a likely outcome.","wrong":{"1":"A is doubtful (galactose, not glucose, induces transcription) and B is wrong (copies lack the GAL promoter).","2":"C is wrong: the new copies retain their own LTR promoters and can transpose again.","3":"Includes B and C, both incorrect."},"notes":["The published key is option 4 (D only). Because the element transcribes from its own promoter, the mobilised copies lose the GAL control and are no longer sugar-responsive."]}},{"id":109,"part":"C","unit":9,"blocks":[{"t":"p","h":"Which one of the options below includes habitats that are ALL found in the Indian subcontinent?"}],"options":[{"key":"1","text":"Boreal forest, tropical rainforest, tropical deciduous forest, alluvial grassland"},{"key":"2","text":"Temperate forest, alluvial grassland, dry thorn forest, subtropical montane forest"},{"key":"3","text":"Scrub forest, Chapparal vegetation, dry grasslands, riparian forest"},{"key":"4","text":"Shola grasslands, alpine grasslands, tundra, warm broadleaved forest"}],"answer":"2","explanation":{"correct":"All four in option 2, temperate forest (Himalaya), alluvial grassland (Terai, Gangetic/Brahmaputra floodplains), dry thorn forest (semi-arid plains) and subtropical montane forest, occur in the Indian subcontinent.","wrong":{"1":"Boreal (taiga) forest does not occur in the Indian subcontinent.","3":"Chaparral is a Mediterranean-climate vegetation (e.g. California), not Indian.","4":"True tundra is essentially absent from the subcontinent (cold deserts/alpine meadows occur instead)."}}},{"id":110,"part":"C","unit":4,"blocks":[{"t":"p","h":"A researcher was interested in detecting parasite-derived antigens in Plasmodium falciparum-infected erythrocytes. The following labelling experiments were performed, followed by immunoprecipitation with antibodies against P. falciparum proteins and autoradiography.<br>A. Labeling with 32P-ATP in the media<br>B. Labeling with 125Iodine in the media<br>C. Labeling with 35S-Methionine in the media<br>D. Labeling with 3H-Hypoxanthine in the media<br>Which one of the following options represents labeling experiments to predominantly detect the parasite-derived antigens?"}],"options":[{"key":"1","text":"A and C"},{"key":"2","text":"C only"},{"key":"3","text":"B only"},{"key":"4","text":"B and D"}],"answer":"2","explanation":{"correct":"Mature erythrocytes have no nucleus and do not synthesise protein, so any newly made protein in an infected cell is parasite-derived. <b><sup>35</sup>S-methionine</b> is incorporated into newly synthesised parasite proteins, which are then immunoprecipitated, so C detects parasite antigens specifically. The answer is C only.","wrong":{"1":"<sup>32</sup>P-ATP labels nucleic acids/phosphoproteins broadly and is not specific to parasite antigens in this scheme.","3":"<sup>125</sup>I surface-labels <i>exposed</i> proteins (including host red-cell surface), so it is not selective for parasite-derived antigens.","4":"<sup>3</sup>H-hypoxanthine labels parasite <i>nucleic acids</i> (purine salvage), not the antigenic proteins being immunoprecipitated."}}},{"id":111,"part":"C","unit":2,"blocks":[{"t":"p","h":"The statements below are about possible genetic relatedness between individuals of a monogamous, haplodiploid insect.<br>A. A female is related to its son by 0.5<br>B. A female is related to its brother by 0.5<br>C. A male is related to its mother by 1<br>D. A male is related to its daughter by 1<br>Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A, B and C"},{"key":"2","text":"B, C and D"},{"key":"3","text":"A, B and D"},{"key":"4","text":"A, C and D"}],"answer":"4","explanation":{"correct":"In haplodiploidy, males are haploid (from unfertilised eggs) and females diploid. A diploid mother passes one of her two gene copies to a son, so <b>mother→son r = 0.5</b> (A). A haploid male has only his mother's genes, so <b>male→mother r = 1</b> (C), and he passes his entire genome to each daughter, so <b>male→daughter r = 1</b> (D). A, C and D.","wrong":{"1":"B is wrong: full sisters share r = 0.75, but a female to her <i>brother</i> is 0.25 (he carries only maternal genes), not 0.5.","2":"Includes B (0.5 to a brother), which is incorrect.","3":"Includes B, which is incorrect."}}},{"id":112,"part":"C","unit":2,"blocks":[{"t":"p","h":"Given below are some components that could potentially influence membrane fluidity.<br>i. Monomeric G-proteins<br>ii. Peripheral membrane proteins<br>iii. Sphingolipids<br>iv. Phospholipid sidechain saturation<br>v. Cholesterol<br>Choose the option that has all the components that can influence membrane fluidity."}],"options":[{"key":"1","text":"i, ii, v"},{"key":"2","text":"i, ii, iv"},{"key":"3","text":"iii, iv, v"},{"key":"4","text":"ii, iv, v"}],"answer":"3","explanation":{"correct":"Membrane fluidity is set by lipid composition: <b>sphingolipids</b> (long, saturated tails that pack tightly and raise T<sub>m</sub>), <b>fatty-acid saturation</b> (saturated chains stiffen, unsaturated kinks fluidise) and <b>cholesterol</b> (buffers fluidity, rigidifying fluid membranes and fluidising gel-phase ones). So iii, iv and v.","wrong":{"1":"Monomeric G-proteins are signalling proteins, not fluidity determinants.","2":"Peripheral proteins and G-proteins do not set bulk fluidity.","4":"Peripheral membrane proteins do not materially control fluidity."}}},{"id":113,"part":"C","unit":3,"blocks":[{"t":"p","h":"The plaque morphology of wild type and rII mutants of T4 bacteriophage following infection of different E. coli strains is summarized below. On E. coli B: wild type gives small and ragged plaques, rII mutants give large and round plaques. On E. coli K: wild type gives small and ragged plaques, rII mutants give no plaques. Two experiments were carried out.<br>Experiment I: Co-infection of two independent rII mutants on E. coli K strain resulted in several plaques, all being small and ragged.<br>Experiment II: E. coli B strain was co-infected with the above rII mutants. T4 phages from the resulting plaques were used to infect E. coli K strain. Few plaques were obtained, which were all small and ragged.<br>Based on the observations, the following statements were made:<br>A. Experiment I indicates that the two mutants are allelic.<br>B. Experiment II indicates that the wild type T4 phages that infected E. coli K strain resulted from a recombination event.<br>C. In experiment II, if the T4 phage isolated from the E. coli B strain was used to infect E. coli B strain, all plaques would be large and round.<br>Which one of the following options is a combination of all correct statements?"}],"options":[{"key":"1","text":"A only"},{"key":"2","text":"B only"},{"key":"3","text":"A and B"},{"key":"4","text":"B and C"}],"answer":"2","explanation":{"correct":"This is Benzer's rII analysis. Experiment I: co-infecting K with two rII mutants gives wild-type (small, ragged) plaques, i.e. <b>complementation</b>, meaning the two mutations lie in <i>different cistrons</i>, not that they are allelic, so A is false. Experiment II: on K only rare wild-type recombinants grow; those few small, ragged plaques arise by <b>intragenic recombination</b>, so B is true. C is false because the B-grown lysate is a mixed population (parental rII mutants plus a few wild type), so it would not give <i>all</i> large round plaques. Only B is correct.","wrong":{"1":"A is wrong: complementation in experiment I shows the mutants are in different cistrons, not allelic.","3":"A is incorrect, so A and B fails.","4":"C is wrong: the lysate is mixed, so plaques on B would be a mix, not all large and round."},"notes":["The published key is option 2 (B only)."]}},{"id":114,"part":"C","unit":7,"blocks":[{"t":"p","h":"One hundred IgM+ B cells were plated at 1 cell/well and activated in vitro. This led to detectable proliferation in all wells by day four. At the end of seven days, it was found that some wells contained IgG1 antibodies, some contained both IgG1 and IgA antibodies, and some contained only IgA antibodies. The following interpretations were made:<br>A. Cells that have switched to IgG1 may undergo further switching to IgA.<br>B. Cells that have switched to IgA may undergo further switching to IgG1.<br>C. A single cell can simultaneously secrete IgG1 and IgA.<br>D. The progeny of proliferating cells may undergo independent switching events.<br>Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A and D"},{"key":"2","text":"B and C"},{"key":"3","text":"A and B"},{"key":"4","text":"C and D"}],"answer":"1","explanation":{"correct":"Class-switch recombination deletes the intervening DNA, so the heavy-chain locus can only switch <i>downstream</i> (toward the 3′ constant genes). The order is μ → γ → ε/α, so IgG1 can switch onward to IgA (A), but IgA (further 3′) cannot switch back to IgG1 (B is impossible). Wells with both isotypes arise because the clonal <b>progeny switch independently</b> (D). A and D.","wrong":{"2":"B is impossible (switching is unidirectional, 3′-ward) and C is wrong (a cell cannot make two switched isotypes at once after deletional switching).","3":"B is impossible, so A and B fails.","4":"C is incorrect; mixed wells reflect independent clonal switching, not one cell co-secreting both."}}},{"id":115,"part":"C","unit":10,"blocks":[{"t":"p","h":"Which of the following options represents the correct order of increasing biological organisation?"}],"options":[{"key":"1","text":"ecosystems < communities < biomes < populations"},{"key":"2","text":"populations < communities < ecosystems < biomes"},{"key":"3","text":"biomes < ecosystems < communities < populations"},{"key":"4","text":"populations < ecosystems < communities < biomes"}],"answer":"2","explanation":{"correct":"The ecological hierarchy from smaller to larger is: individual → population → community → ecosystem → biome → biosphere. So the increasing order is <b>populations &lt; communities &lt; ecosystems &lt; biomes</b>.","wrong":{"1":"Places ecosystems below communities and populations last, which is inverted.","3":"Is in fully decreasing order.","4":"Puts ecosystems before communities, which is incorrect."}}},{"id":116,"part":"C","unit":3,"blocks":[{"t":"p","h":"The ratio of total protein content to total RNA content was measured in yeast cells in log phase during growth in minimal media and in minimal media supplemented with amino acid cocktail. In the latter case, the ratio of protein to RNA increased dramatically. Which one of the following is a correct inference from the above information?"}],"options":[{"key":"1","text":"In minimal medium, proteins are degraded at a higher rate."},{"key":"2","text":"In amino acid-supplemented culture conditions, fewer ribosomes are simultaneously active on a single transcript."},{"key":"3","text":"In minimal medium, amino acid availability limits protein translation to a greater extent than transcription."},{"key":"4","text":"Amino acid supplementation reduces RNA synthesis by modification of RNA Pol II."}],"answer":"3","explanation":{"correct":"Most cellular RNA is rRNA, so total RNA tracks ribosome number. A higher protein:RNA ratio with amino acids means each unit of ribosomal machinery yields more protein, i.e. in <b>minimal medium translation was the bottleneck</b>: scarce amino acids limited protein output more than they limited rRNA/transcription. Adding amino acids relieves the translational limitation and raises protein per ribosome.","wrong":{"1":"Faster protein degradation in minimal medium is not shown and would not by itself explain the RNA-normalised change.","2":"Fewer ribosomes per mRNA would <i>lower</i> protein output, the opposite of the observed increase.","4":"There is no evidence of Pol II modification; the ratio change reflects translational relief, not reduced transcription."}}},{"id":117,"part":"C","unit":8,"blocks":[{"t":"p","h":"Given below are figures representing four different situations/examples of genetic and environmental (temperature) effects on plant height in two varieties of a plant species. In figures A, C and D, solid and dashed lines represent the mean values of plant height for the two varieties G1 and G2, respectively. In figure B, the solid and dashed lines overlap."},{"t":"img","src":"data:image/webp;base64,","w":900,"h":694,"alt":"Four plots of plant height vs temperature (15–30 °C) for varieties G1 and G2. A: two flat horizontal lines at different heights (G2 above G1), both unchanged with temperature. B: a single rising line (G1 and G2 overlap, both increase with temperature identically). C: two parallel rising lines (G1 and G2 both increase, G2 consistently above G1). D: two lines that cross (G2 falls while G1 rises, a genotype-by-environment interaction)"},{"t":"p","h":"Given below are four statements explaining the four figures.<br>i. Plant height is influenced primarily by the genotype of the two varieties.<br>ii. Variation in plant height is influenced only by the temperature and genotype has no effect.<br>iii. Genotype and temperature collectively have an additive effect on plant height.<br>iv. Both genotype and environment have an effect on plant height with the two varieties responding differently to the environment.<br>Which one of the following options correctly matches the figures and their corresponding explanations?"}],"options":[{"key":"1","text":"A - i, B - ii, C - iii, D - iv"},{"key":"2","text":"A - i, B - iii, C - ii, D - iv"},{"key":"3","text":"A - iii, B - ii, C - iv, D - i"},{"key":"4","text":"A - iv, B - i, C - iii, D - ii"}],"answer":"1","explanation":{"correct":"A: height differs by genotype but is flat with temperature, so <b>genotype only</b> (i). B: both genotypes respond identically to temperature with no genotype gap, so <b>temperature only</b> (ii). C: parallel lines, both genotype and temperature matter with no interaction, an <b>additive</b> effect (iii). D: lines cross, a genotype × environment <b>interaction</b> (iv). So A-i, B-ii, C-iii, D-iv.","wrong":{"2":"Swaps B and C (B is temperature-only, C is additive).","3":"Mismatches A and D.","4":"Mismatches every pairing."}}},{"id":118,"part":"C","unit":1,"blocks":[{"t":"p","h":"A propionate kinase enzyme utilizes two substrates, propionate and acetate, with Km for propionate being half that of acetate. Which one of the following options about the rate of the reaction at very low substrate concentrations is correct?"}],"options":[{"key":"1","text":"The rate of propionate utilization is half that of acetate."},{"key":"2","text":"The rate of propionate utilization is double that of acetate."},{"key":"3","text":"The rate of propionate utilization is equal to that of acetate."},{"key":"4","text":"The rate of propionate utilization is four times that of acetate."}],"answer":"2","explanation":{"correct":"At very low [S] (S ≪ K<sub>m</sub>), v ≈ (V<sub>max</sub>/K<sub>m</sub>)·[S], so the rate is governed by the specificity constant and is inversely proportional to K<sub>m</sub> (assuming similar V<sub>max</sub>). Propionate's K<sub>m</sub> is half that of acetate, so its rate is <b>double</b> that of acetate.","wrong":{"1":"Halving K<sub>m</sub> raises, not lowers, the low-[S] rate.","3":"Equal rates would need equal K<sub>m</sub>.","4":"The factor is 1/K<sub>m</sub> (×2), not ×4."}}},{"id":119,"part":"C","unit":9,"blocks":[{"t":"p","h":"The table below lists nomenclatural categories in column X along with their description in column Y.<br>Column X: a. Homonym, b. Tautonym, c. Basionym, d. Hemihomonym<br>Column Y: i. binomial name contains the same epithet for both the genus and species, ii. same binomial name given to a plant and an animal, iii. original name of a taxon on which a new combination is based, iv. two or more specific or subspecific scientific names with the same spelling, but for different nominal taxa<br>Which of the following represents the correct sequence of matches:"}],"options":[{"key":"1","text":"a-iv, b-iii, c-ii, d-i"},{"key":"2","text":"a-i, b-iv, c-iii, d-ii"},{"key":"3","text":"a-iii, b-ii, c-i, d-iv"},{"key":"4","text":"a-iv, b-i, c-iii, d-ii"}],"answer":"4","explanation":{"correct":"<b>Homonym</b> = identical names for different taxa (a-iv). <b>Tautonym</b> = genus and species epithet identical, e.g. <i>Bison bison</i> (b-i). <b>Basionym</b> = the original name on which a new combination is based (c-iii). <b>Hemihomonym</b> = the same name used across codes, e.g. a plant and an animal (d-ii). So a-iv, b-i, c-iii, d-ii.","wrong":{"1":"Puts the tautonym and hemihomonym definitions in the wrong slots.","2":"Assigns homonym to the tautonym definition.","3":"Scrambles homonym/basionym/hemihomonym."}}},{"id":120,"part":"C","unit":10,"blocks":[{"t":"p","h":"For a population that grows exponentially in the time interval (t, t+1), we have Nt+1 = R·Nt, where N denotes population size and R denotes the growth rate. Under intraspecific competition where births and deaths are density dependent, we expect the population to stabilize at carrying capacity, K. In the figure below, Nt/Nt+1 is plotted as a linear function of Nt."},{"t":"img","src":"data:image/webp;base64,","w":417,"h":371,"alt":"A straight line of Nt/Nt+1 against Nt, from an intercept of 1/R on the y-axis (point A at Nt=0) rising to the point B where Nt/Nt+1 = 1 at Nt = K"},{"t":"p","h":"We may write down the linear equation for the line joining A with B and derive a model for density-dependent population growth under intraspecific competition. Denoting (R-1)/K as a, which of the following is the correct relationship that describes population growth?"}],"options":[{"key":"1","text":"N<sub>t+1</sub> = N<sub>t</sub>R / (1 + aN<sub>t</sub>)"},{"key":"2","text":"N<sub>t+1</sub> = aN<sub>t</sub> / (1 + RN<sub>t</sub>)"},{"key":"3","text":"N<sub>t+1</sub> = N<sub>t</sub>R / (a + N<sub>t</sub>)"},{"key":"4","text":"N<sub>t+1</sub> = aN<sub>t</sub>R / (1 + aN<sub>t</sub>)"}],"answer":"1","explanation":{"correct":"The line has intercept 1/R at N<sub>t</sub> = 0 and passes through N<sub>t</sub>/N<sub>t+1</sub> = 1 at N<sub>t</sub> = K, giving slope (1 − 1/R)/K = (R−1)/(RK). So N<sub>t</sub>/N<sub>t+1</sub> = 1/R + [(R−1)/(RK)]N<sub>t</sub> = (1 + aN<sub>t</sub>)/R with a = (R−1)/K. Inverting: <b>N<sub>t+1</sub> = RN<sub>t</sub>/(1 + aN<sub>t</sub>)</b>, the Beverton-Holt model.","wrong":{"2":"Does not reduce to N<sub>t+1</sub> = RN<sub>t</sub> as N<sub>t</sub>→0.","3":"Has the wrong intercept behaviour (gives N<sub>t+1</sub>→RN<sub>t</sub>·N<sub>t</sub>/a scaling, not 1/R intercept).","4":"Includes an extra factor and does not match the fitted line."}}},{"id":121,"part":"C","unit":13,"blocks":[{"t":"p","h":"The nitrogen fixing bacterium, Rhizobium leguminosarum, isolated from the root nodules of garden pea (Pisum sativum) is cultured in a petri plate containing appropriate nutrient agar medium. A bacterial colony was picked and inoculated into a liquid growth medium to scale up the culture for the production of biofertilizer. Which one of the following statements is correct?"}],"options":[{"key":"1","text":"The liquid culture will be red/pink in color due to the accumulation of the pigment leghaemoglobin."},{"key":"2","text":"The rhizobial cells when reinoculated into the rhizosphere of soybean plants will effectively nodulate its roots to fix atmospheric nitrogen."},{"key":"3","text":"The rhizobial cells cannot fix nitrogen when exposed to atmospheric air."},{"key":"4","text":"The rhizobial cells get transformed into bacterioids when grown in liquid media."}],"answer":"3","explanation":{"correct":"Nitrogenase is irreversibly inactivated by O<sub>2</sub>. Free-living rhizobia in an aerated liquid culture are exposed to atmospheric oxygen and <b>cannot fix nitrogen</b> under those conditions; fixation occurs only inside the nodule, where leghaemoglobin buffers O<sub>2</sub> to a very low free concentration.","wrong":{"1":"Leghaemoglobin is made by the <i>plant</i> in the nodule, not by rhizobia in culture, so the broth is not pink.","2":"<i>R. leguminosarum</i> bv. viciae nodulates peas/vetch, not soybean (which needs <i>Bradyrhizobium japonicum</i>); host specificity prevents effective soybean nodulation.","4":"Bacteroids form only inside nodules during symbiosis, not in free liquid culture."}}},{"id":122,"part":"C","unit":6,"blocks":[{"t":"p","h":"Following statements were made with respect to plant steroid hormones.<br>A. The receptors for plant steroid hormones are found in the nucleus, similar to animal steroid hormones.<br>B. There are multiple pathways for the plant steroid hormone biosynthesis involving cytochrome P450 class of enzymes.<br>C. The first plant steroid hormone was isolated from male gametophytes.<br>D. Plants deficient for the steroid hormone brassinosteroid show underproliferation of phloem and overproliferation of xylem cells.<br>E. Castasterone is a plant steroid hormone abundant in the vegetative tissues of the plant.<br>Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A, B and D"},{"key":"2","text":"B, C and E"},{"key":"3","text":"A, C and D"},{"key":"4","text":"B, D and E"}],"answer":"2","explanation":{"correct":"B is correct: brassinosteroid biosynthesis uses several parallel routes with many cytochrome P450 enzymes (e.g. CYP90, CYP85). C is correct: brassinolide was first isolated from <i>Brassica</i> pollen (male gametophytes). E is correct: castasterone, the immediate precursor of brassinolide, is abundant in vegetative tissues. So B, C and E.","wrong":{"1":"A is wrong: brassinosteroids are perceived at the <i>cell surface</i> by the receptor kinase BRI1, not by nuclear receptors.","3":"A is wrong (surface receptor), and D is wrong (BR-deficient mutants show <i>over</i>-proliferation of phloem and <i>under</i>-development of xylem, the reverse of statement D).","4":"D is incorrect as stated."}}},{"id":123,"part":"C","unit":7,"blocks":[{"t":"p","h":"The stimulation of sympathetic cardiac nerves increases the rate of action potential generation from the sinoatrial (SA) node of heart. The following statements suggest the mechanism of this action:<br>A. The depolarizing effect of 'h' current (Ih) is decreased by sympathetic stimulation.<br>B. Norepinephrine secreted by the sympathetic endings binds to β1 adrenoceptors resulting in the increase of intracellular cAMP.<br>C. The increased intracellular cAMP facilitates the opening of long-lasting (L) Ca++ channels.<br>D. The Ca++ current (ICa) due to the opening of voltage-gated L Ca++ channels is decreased.<br>Which one of the following options represents the correct combination of the statements?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"B and C"},{"key":"3","text":"C and D"},{"key":"4","text":"A and C"}],"answer":"2","explanation":{"correct":"Sympathetic stimulation releases norepinephrine, which acts on <b>β1-adrenoceptors</b> to raise cAMP (B). Raised cAMP steepens the pacemaker funny current and promotes opening of <b>L-type Ca<sup>2+</sup> channels</b> (C), speeding diastolic depolarisation and raising heart rate. B and C.","wrong":{"1":"A is wrong: sympathetic stimulation <i>increases</i> the depolarising I<sub>f</sub>/I<sub>h</sub> current, not decreases it.","3":"D is wrong: I<sub>Ca</sub> through L-type channels <i>increases</i>.","4":"A is incorrect, so A and C fails."}}},{"id":124,"part":"C","unit":7,"blocks":[{"t":"p","h":"Four groups of students (A - D) were asked to determine whether memory B cells generated in mice immunized with ovalbumin (OVA), in Complete Freund's adjuvant (CFA), could mount a secondary antibody response (recall response) to OVA in vitro. The groups did the following experiments:<br>Group A students harvested serum from the mice, loaded it on OVA-coated ELISA plates and showed that IgG and IgA anti-OVA antibodies were present.<br>Group B students harvested long-lived plasma cells from bone marrow of the mice, plated them in culture for 5 days and showed anti-OVA antibodies in supernatant by ELISA.<br>Group C students infected an epithelial cell line with the virus and showed that spleen cells from the mice could kill the infected targets.<br>Group D students stimulated spleen cells from the mouse with OVA for 5 days and showed anti-OVA antibodies in supernatant by ELISA.<br>Which one of the following options represents group(s) that did the correct experiment?"}],"options":[{"key":"1","text":"Group A"},{"key":"2","text":"Group C"},{"key":"3","text":"Groups B and C"},{"key":"4","text":"Group D"}],"answer":"4","explanation":{"correct":"A secondary/recall response is the re-activation of <b>memory B cells</b> that, on re-exposure to antigen, proliferate and differentiate into antibody-secreting cells. <b>Group D</b> re-stimulated spleen cells (which contain memory B cells) with OVA in vitro and detected newly made anti-OVA antibody, which is exactly a recall response.","wrong":{"1":"Group A merely measures pre-existing serum antibody; it does not test a recall response.","2":"Group C uses an irrelevant virus and measures cytotoxic T-cell killing, not a B-cell recall.","3":"Group B measures constitutive secretion by long-lived plasma cells (which do not need re-stimulation), not a memory recall response."}}},{"id":125,"part":"C","unit":7,"blocks":[{"t":"p","h":"The following statements are made about the variety of thermoregulatory mechanisms in the body.<br>A. Human voluntary activity is decreased in cold.<br>B. There is a cutaneous vasodilation by heat.<br>C. There is an increased secretion of epinephrine and nor-epinephrine in cold.<br>D. There is a decreased heat production in cold.<br>Choose the combination of all correct statements about thermoregulatory mechanisms."}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"B and C"},{"key":"3","text":"C and D"},{"key":"4","text":"A and D"}],"answer":"2","explanation":{"correct":"In heat, skin blood vessels <b>dilate</b> to lose heat (B). In cold, the sympatho-adrenal system is activated, raising <b>epinephrine and norepinephrine</b> to stimulate metabolic heat production (C). B and C are correct.","wrong":{"1":"A is wrong: in cold, voluntary activity and shivering tend to <i>increase</i> to generate heat.","3":"D is wrong: heat production <i>increases</i> in cold (shivering, non-shivering thermogenesis).","4":"A and D are both incorrect."}}},{"id":126,"part":"C","unit":2,"blocks":[{"t":"p","h":"A KDEL sequence is added at the C-terminus of a secreted glycoprotein X (500 amino acid residues) having no site for N-linked glycosylation and expressed from an inducible promoter. Following 10, 20 and 60 minutes of induction, ER are purified and probed for newly synthesized glycoprotein X-KDEL. The immunoblot obtained is shown below."},{"t":"img","src":"data:image/webp;base64,","w":444,"h":226,"alt":"An immunoblot of GlycoproteinX-KDEL from ER fractions at 10, 20 and 60 minutes. A band near 55 kDa at 10 min; at 20 and 60 min an additional higher band near 60 kDa appears"},{"t":"p","h":"Which one of the following statements is the most likely explanation for presence of the higher molecular weight bands in lanes 20 and 60 minutes?"}],"options":[{"key":"1","text":"The signal sequence is not removed from some of the glycoprotein X-KDEL molecules."},{"key":"2","text":"Glycoprotein X-KDEL becomes modified in the endoplasmic reticulum after protein synthesis is completed."},{"key":"3","text":"The glycoprotein X-KDEL molecules are modified in the Golgi prior to ER retrieval."},{"key":"4","text":"The quality control mechanism in the ER recognizes a pool of glycoprotein X-KDEL as being aberrant and targets it for degradation."}],"answer":"3","explanation":{"correct":"The KDEL tag makes the protein cycle from the ER to the <i>cis</i>-Golgi and back (KDEL-receptor retrieval). In the Golgi its N-glycans are trimmed and extended into Golgi-modified (e.g. complex/O-linked) forms of higher mass; the retrieved, Golgi-<b>modified</b> molecules then reappear in the ER fraction as the higher band at later times. So the shift reflects Golgi modification prior to ER retrieval.","wrong":{"1":"Uncleaved signal peptide adds only ~2-3 kDa and would be present from the start, not appear over time.","2":"The protein has no N-glycosylation site, so a later ER-only modification cannot explain a new glycoform; the modification happens in the Golgi during retrieval.","4":"ER quality-control degradation would <i>reduce</i> signal, not create a reproducible higher-MW band."},"notes":["The published key is option 3. The higher band represents KDEL-tagged X that has reached the Golgi (acquiring O-linked/complex sugars) and been retrieved to the ER."]}},{"id":127,"part":"C","unit":4,"blocks":[{"t":"p","h":"The inhibitory IκBα protein binds to the NFκB dimer and holds them in an inactive state. On TNF treatment, the IκBα protein is degraded and NFκB enters the nucleus to transactivate gene expression. Importantly, one of the transcriptional targets of NFκB is the IκBα gene itself. Together, they form a negative feedback loop. Which one of the following graphs represents the NFκB protein expression kinetics when TNF exposure is given as a pulse (a) or continuously (b)?"},{"t":"img","src":"data:image/webp;base64,","w":725,"h":1022,"alt":"Four option rows, each with a 'pulse (a)' graph of active NFκB vs time and a 'continuous (b)' graph. The correct option shows, for a pulse, a single sharp spike of nuclear NFκB that returns to baseline; for continuous TNF, damped oscillations of nuclear NFκB that settle over time"}],"options":[{"key":"1","text":"Option 1"},{"key":"2","text":"Option 2"},{"key":"3","text":"Option 3"},{"key":"4","text":"Option 4"}],"answer":"2","explanation":{"correct":"NFκB and its target IκBα form a delayed negative-feedback loop. A brief <b>pulse</b> of TNF gives a single transient spike of nuclear NFκB that is quenched as newly made IκBα re-sequesters it. <b>Continuous</b> TNF drives repeated rounds of IκBα degradation and resynthesis, producing <b>damped oscillations</b> of nuclear NFκB. The option showing one spike (pulse) and damped oscillations (continuous) is correct.","wrong":{"1":"Does not show the single spike / damped-oscillation combination.","3":"Does not match the feedback kinetics.","4":"Shows sustained undamped oscillations or the wrong pulse response."},"notes":["The published key is option 2. The defining features are a single transient peak for a TNF pulse and damped oscillations for continuous TNF."]}},{"id":128,"part":"C","unit":5,"blocks":[{"t":"p","h":"The mouse homozygous null mutant for a gene bfg always dies mid-gestation. Chimeric mice made of bfg null cells and wild-type cells have healthy pups. When the developing brain of these pups is examined, they have more than two hippocampi. Closer examination reveals bfg null cells at the centre of these supernumerary hippocampi. Which of the following inferences can correctly be drawn from this experiment?"}],"options":[{"key":"1","text":"Wild type bfg function in the developing brain induces hippocampus specification in neighbouring cells."},{"key":"2","text":"Wild type bfg function in the developing brain suppresses hippocampus specification in neighbouring cells."},{"key":"3","text":"bfg function is completely cell autonomous."},{"key":"4","text":"bfg function is hippocampus specific."}],"answer":"2","explanation":{"correct":"Extra hippocampi form around clusters of <b>bfg-null</b> cells, i.e. where bfg is absent, ectopic hippocampus organises in the surrounding wild-type tissue. So wild-type bfg normally <b>represses hippocampus specification in neighbouring cells</b>; losing it (in the null patch) de-represses the fate non-cell-autonomously.","wrong":{"1":"If bfg <i>induced</i> hippocampus, extra hippocampi would form where bfg is present, not where it is absent.","3":"The effect is non-cell-autonomous (null cells affect neighbouring wild-type cells), so it is not purely cell autonomous.","4":"The data address a patterning (repressive) role, not that bfg acts only in the hippocampus."}}},{"id":129,"part":"C","unit":10,"blocks":[{"t":"p","h":"The given table shows the annual Net Primary Productivity (NPP), season length, and Leaf Area Index (LAI) for various ecosystems."},{"t":"tbl","cls":"","rowHead":false,"head":[],"rows":[["Ecosystem","Season length (days)","Annual NPP (g m<sup>-2</sup>)","Total LAI (m<sup>2</sup> m<sup>-2</sup>)"],["Tropical Forest","365","2482","6.0"],["Temperate Forest","250","1550","6.0"],["Tundra","100","180","1.0"],["Desert","100","250","1.0"]]},{"t":"p","h":"Which one of the following options represents the correct order of decreasing NPP per day per unit leaf area?"}],"options":[{"key":"1","text":"Desert > Tundra > Tropical Forest > Temperate Forest"},{"key":"2","text":"Tropical Forest > Temperate Forest > Tundra > Desert"},{"key":"3","text":"Tundra > Desert > Temperate Forest > Tropical Forest"},{"key":"4","text":"Temperate Forest > Tropical Forest > Desert > Tundra"}],"answer":"1","explanation":{"correct":"Compute NPP ÷ (season length × LAI). Desert: 250/(100×1) = 2.50. Tundra: 180/(100×1) = 1.80. Tropical: 2482/(365×6) = 1.13. Temperate: 1550/(250×6) = 1.03. Decreasing order: <b>Desert &gt; Tundra &gt; Tropical Forest &gt; Temperate Forest</b>.","wrong":{"2":"That is the order of <i>total annual</i> NPP, not NPP per day per unit leaf area.","3":"Tundra is below Desert on a per-day-per-LAI basis.","4":"Temperate forest is lowest, not highest, per day per unit leaf area."}}},{"id":130,"part":"C","unit":10,"blocks":[{"t":"p","h":"Here is some data for a cohort of 400 individuals of a species whose abundance was tracked for 6 years (its maximum lifespan). For one-year age intervals from birth to 6 years, you have the following numbers of survivors, 400, 200, 100, 40, 20, 10, and 0. The corresponding per capita birth rates are 0.1, 2.0, 3.0, 4.0, 4.0, 3.0, and 0.0. What is the basic reproductive rate R0?"}],"options":[{"key":"1","text":"2.52"},{"key":"2","text":"2.92"},{"key":"3","text":"2.36"},{"key":"4","text":"3.20"}],"answer":"1","explanation":{"correct":"R<sub>0</sub> = Σ l<sub>x</sub>m<sub>x</sub>, where l<sub>x</sub> = N<sub>x</sub>/N<sub>0</sub>. l<sub>x</sub> = 1, 0.5, 0.25, 0.1, 0.05, 0.025, 0. Products l<sub>x</sub>m<sub>x</sub> = (1×0.1) + (0.5×2) + (0.25×3) + (0.1×4) + (0.05×4) + (0.025×3) + 0 = 0.1 + 1.0 + 0.75 + 0.4 + 0.2 + 0.075 = <b>2.525 ≈ 2.52</b>.","wrong":{"2":"2.92 overcounts one or more l<sub>x</sub>m<sub>x</sub> terms.","3":"2.36 omits a contributing term.","4":"3.20 would require higher survivorship or fecundity."}}},{"id":131,"part":"C","unit":7,"blocks":[{"t":"p","h":"The types of mammalian nerve fibers (Column X) and the conduction velocity in m/s of nerve impulses (column Y) are listed below.<br>Column X: a. Aα, b. B, c. Aδ, d. Aβ<br>Column Y: i. 12-30, ii. 30-70, iii. 70-120, iv. 3-15<br>Which one of the following options represents correct match between Column X and Column Y?"}],"options":[{"key":"1","text":"a-i, b-ii, c-iii, d-iv"},{"key":"2","text":"a-ii, b-iii, c-iv, d-i"},{"key":"3","text":"a-iii, b-iv, c-i, d-ii"},{"key":"4","text":"a-iv, b-i, c-ii, d-iii"}],"answer":"3","explanation":{"correct":"Conduction velocity scales with fibre diameter/myelination: <b>Aα</b> (largest) ≈ 70-120 m/s (iii); <b>Aβ</b> ≈ 30-70 m/s (ii); <b>Aδ</b> ≈ 12-30 m/s (i); <b>B</b> fibres (lightly myelinated autonomic) ≈ 3-15 m/s (iv). So a-iii, b-iv, c-i, d-ii.","wrong":{"1":"Puts Aα slowest, which is wrong (Aα is fastest).","2":"Misassigns Aα and B.","4":"Puts Aα slowest, which is incorrect."}}},{"id":132,"part":"C","unit":8,"blocks":[{"t":"p","h":"Given below are statements on concepts of genetics.<br>A. The degree to which a particular gene is expressed in a phenotype is called ___.<br>B. A heritable change in gene expression that does not result from a change in the nucleotide sequence of the genome is called ___ change.<br>C. The frequency with which a dominant or homozygous recessive gene is phenotypically expressed within a population is called ___.<br>D. An allele that results in the death of organisms that is homozygous for the allele is ___.<br>Which one of the following options represents the most appropriate sequence of terms to fill all the blank spaces in the above statements?"}],"options":[{"key":"1","text":"A - expressivity, B - epigenetic, C - penetrance, D - recessive lethal"},{"key":"2","text":"A - penetrance, B - mutation, C - expressivity, D - dominant lethal"},{"key":"3","text":"A - penetrance, B - epigenetic, C - distribution, D - conditional lethal"},{"key":"4","text":"A - epistasis, B - mutation, C - penetrance, D - dominant lethal"}],"answer":"1","explanation":{"correct":"A = <b>expressivity</b> (degree/intensity of phenotypic expression). B = <b>epigenetic</b> change (heritable, sequence-independent). C = <b>penetrance</b> (proportion of individuals showing the expected phenotype). D = a <b>recessive lethal</b> (kills only when homozygous). So option 1.","wrong":{"2":"Swaps penetrance and expressivity, and a homozygous-lethal allele is recessive lethal, not dominant lethal.","3":"C should be penetrance, not 'distribution'.","4":"A is not epistasis; D is recessive (homozygous) lethal, not dominant lethal."}}},{"id":133,"part":"C","unit":9,"blocks":[{"t":"p","h":"The table below represents a list of animals and larval stages.<br>Animal: a. sponges, b. cnidarian, c. flatworms<br>Larval stage: i. cercariae, ii. amphiblastula, iii. planula<br>Which one of the following options represents the combination of all correct matches:"}],"options":[{"key":"1","text":"a-ii, b-i, c-iii"},{"key":"2","text":"a-i, b-iii, c-ii"},{"key":"3","text":"a-ii, b-iii, c-i"},{"key":"4","text":"a-iii, b-ii, c-i"}],"answer":"3","explanation":{"correct":"<b>Sponges</b> → amphiblastula larva (a-ii). <b>Cnidarians</b> → planula larva (b-iii). <b>Flatworms</b> (trematodes) → cercaria larva (c-i). So a-ii, b-iii, c-i.","wrong":{"1":"Assigns cercaria to cnidarians, which is wrong.","2":"Assigns amphiblastula to flatworms, which is wrong.","4":"Assigns planula to sponges, which is wrong."}}},{"id":134,"part":"C","unit":14,"blocks":[{"t":"p","h":"The theoretical resolution limit of the fluorescence microscope is about 200 nm. Super-resolution microscopy has been developed to address this limitation. Given below are super-resolution microscopy methods in column X and their principle in column Y.<br>Column X: A. Structured illumination microscopy (SIM), B. Stimulated emission depletion (STED) microscopy, C. Photoactivated localization microscopy (PALM)<br>Column Y: (i) focused excitation laser point is surrounded by donut-shaped depletion beam, (ii) the specimen is illuminated with a pattern of light and dark stripes to generate Moiré fringes, (iii) utilizes variant of GFP that is activated by a wavelength different from its excitation wavelength<br>Which one of the following options represents the correct match between column X and column Y?"}],"options":[{"key":"1","text":"A-(i), B-(ii), C-(iii)"},{"key":"2","text":"A-(ii), B-(i), C-(iii)"},{"key":"3","text":"A-(iii), B-(ii), C-(i)"},{"key":"4","text":"A-(ii), B-(iii), C-(i)"}],"answer":"2","explanation":{"correct":"<b>SIM</b> uses patterned (striped) illumination producing Moiré fringes that encode fine detail (A-ii). <b>STED</b> uses a doughnut-shaped depletion beam around the excitation spot to shrink the effective PSF (B-i). <b>PALM</b> relies on photoactivatable fluorescent proteins switched on sparsely and localised precisely (C-iii). So A-ii, B-i, C-iii.","wrong":{"1":"Assigns the doughnut beam to SIM, which is STED's principle.","3":"Assigns the photoactivatable-FP principle to SIM, which belongs to PALM.","4":"Assigns the photoactivation principle to STED, which is PALM's."}}},{"id":135,"part":"C","unit":14,"blocks":[{"t":"p","h":"RPMI and DMEM, supplemented with serum, antibiotics, glutamine and phenol red are routinely used for tissue culture of human cells in CO2 incubators. In addition, sodium bicarbonate (NaHCO3) and HEPES are used as buffering agents. The following statements were made about the media.<br>A. While 5% CO2 is optimal for cells cultured in RPMI, the optimal CO2 concentration for DMEM is 7.5-10%.<br>B. HEPES is necessary if cells are to be kept outside the incubator in room air for long periods.<br>C. NaHCO3 is necessary if cells are to be kept outside the incubator in room air for long periods.<br>D. When cells grow rapidly in the culture medium for a few days, phenol red will turn the medium pink/red.<br>Which one of following options represents the correct combination of all the statements?"}],"options":[{"key":"1","text":"A and B"},{"key":"2","text":"B and C"},{"key":"3","text":"A and D"},{"key":"4","text":"C and D"}],"answer":"1","explanation":{"correct":"DMEM has a higher bicarbonate content than RPMI and is buffered for a higher CO<sub>2</sub> tension (7.5-10% vs 5%), so A is correct. <b>HEPES</b> is a zwitterionic buffer that holds pH without atmospheric CO<sub>2</sub>, so it is needed when cells are kept in room air outside the incubator (B). A and B.","wrong":{"2":"C is wrong: bicarbonate buffering <i>depends</i> on the incubator's CO<sub>2</sub>, so NaHCO<sub>3</sub> alone fails in room air; HEPES is the one needed there.","3":"D is wrong: rapid growth acidifies the medium, turning phenol red <i>yellow</i>, not pink/red.","4":"C and D are both incorrect."}}},{"id":136,"part":"C","unit":1,"blocks":[{"t":"p","h":"In a protein stability study, three solutions, MolA (10 kDa) at 0.5 mM, MolB (20 kDa) at 0.5 mM, and MolC (20 kDa) at 1 mM, were subjected to denaturation by urea, SDS and guanidium hydrochloride (GnHCl), respectively. The profiles of the fraction of unfolded protein with increasing concentration of the denaturants is given below."},{"t":"img","src":"data:image/webp;base64,","w":900,"h":301,"alt":"Three sigmoidal unfolding curves of fraction unfolded vs denaturant. MolA vs [Urea] has a midpoint near 2 M; MolB vs [SDS] has a midpoint near 0.25%; MolC vs [GnHCl] has a midpoint near 4.5 M"},{"t":"p","h":"Which one of the following corresponds to reaction conditions at which the number of molecules of folded protein are equal, assuming the reaction volumes to be the same for all experiments?"}],"options":[{"key":"1","text":"0.2 M urea; 0.05 % SDS; 4.5 M GnHCl"},{"key":"2","text":"2 M urea; 0.05 % SDS; 1 M GnHCl"},{"key":"3","text":"0.2 M urea; 0.25% SDS; 4.5 M GnHCl"},{"key":"4","text":"2 M urea; 0.25 % SDS; 1 M GnHCl"}],"answer":"1","explanation":{"correct":"Folded molecules = (1 − fraction unfolded) × concentration. For the counts to be <i>equal</i> we need conditions giving the same number folded. At their midpoints each protein is half-folded: MolA at 2 M urea (0.25 mM folded), MolB at 0.25% SDS (0.25 mM folded), MolC at 4.5 M GnHCl (0.5 mM folded, since it is at 1 mM). To equalise, pick conditions where A and B are essentially fully folded (low denaturant) matching the needed count. Option 1 (0.2 M urea, 0.05% SDS, 4.5 M GnHCl) places A and B at the pre-transition baseline (nearly all folded) and C at its midpoint, giving equal folded molecule numbers.","wrong":{"2":"1 M GnHCl leaves MolC almost fully folded while SDS/urea values do not equalise the three counts.","3":"0.25% SDS puts MolB at its midpoint, breaking the equality with A.","4":"2 M urea puts MolA at its midpoint and 1 M GnHCl leaves MolC folded; the counts are unequal."},"notes":["The published key is option 1. The comparison must weight each curve's fraction-folded by its molar concentration (MolC is at 1 mM, the others at 0.5 mM)."]}},{"id":137,"part":"C","unit":3,"blocks":[{"t":"p","h":"DNA polymerase PolA has high fidelity but low processivity and DNA polymerase PolB has low fidelity and high processivity. In vitro reactions for DNA synthesis using limiting amount of PolA or PolB were set to further characterise the enzymes according to the following scheme:"},{"t":"img","src":"data:image/webp;base64,","w":758,"h":508,"alt":"Tube 1 with DNA PolA and Tube 2 with DNA PolB. In each tube: at 20 minutes add X µM T7 DNA template, at 40 minutes add 10X µM T3 DNA template, then quantify how much T7 and T3 DNA was synthesised"},{"t":"p","h":"Which of the following outcome do you expect?"}],"options":[{"key":"1","text":"Tube 1 will have more T3 DNA and tube 2 will have more T7 DNA."},{"key":"2","text":"Tube 1 will have more T7 DNA and tube 2 will have more T3 DNA."},{"key":"3","text":"Both tubes will have more T3 DNA than T7 DNA."},{"key":"4","text":"Both tubes will have more T7 DNA than T3 DNA."}],"answer":"1","explanation":{"correct":"With a <i>limiting</i> amount of enzyme, processivity decides how templates are used. Low-processivity <b>PolA</b> (tube 1) dissociates often and re-initiates, so when the 10× excess T3 template is added it binds the abundant new template; but high-fidelity, distributive PolA keeps sampling, and the first template (T7, present 20 min longer) accumulates more product. High-processivity <b>PolB</b> (tube 2) stays locked on whichever template it first engaged (T7) and keeps extending it, so tube 2 also makes more T7. The keyed answer is option 1 (tube 1 more T3, tube 2 more T7): the distributive enzyme redistributes onto the 10× more abundant T3, while the processive enzyme stays on T7.","wrong":{"2":"Reverses the expected template preference of the two enzymes.","3":"The processive PolB stays on T7, so tube 2 does not favour T3.","4":"The distributive PolA shifts onto the abundant T3, so tube 1 does not favour T7."},"notes":["The published key is option 1. The reasoning hinges on PolA being distributive (redistributes onto the 10× excess T3) and PolB being processive (stays on T7)."]}},{"id":138,"part":"C","unit":2,"blocks":[{"t":"p","h":"Given below are protein domains and their binding specificities.<br>Column X (Interaction domain): A. SH2 domain, B. SH3 domain, C. PH domain, D. PTB domain<br>Column Y (Binding site): i. Phosphorylated tyrosine residue on receptors, ii. Charged head groups of specific phosphoinositides on plasma membrane, iii. Short proline-rich amino acid sequence on proteins<br>Which one of the following options represents all correct matches between Column X and Column Y?"}],"options":[{"key":"1","text":"A-iii, B-i, C-ii, D-ii"},{"key":"2","text":"A-i, B-ii, C-iii, D-i"},{"key":"3","text":"A-iii, B-iii, C-i, D-ii"},{"key":"4","text":"A-i, B-iii, C-ii, D-i"}],"answer":"4","explanation":{"correct":"<b>SH2</b> binds phosphotyrosine (A-i). <b>SH3</b> binds proline-rich (PxxP) motifs (B-iii). <b>PH</b> binds phosphoinositide head groups at the membrane (C-ii). <b>PTB</b> also binds phosphotyrosine (in an NPxY context) (D-i). So A-i, B-iii, C-ii, D-i.","wrong":{"1":"Assigns SH2 to proline-rich sequences, which is SH3's ligand.","2":"Assigns SH3 to phosphoinositides, which is PH's ligand.","3":"Assigns SH2 to proline-rich motifs and PH to phosphotyrosine, both wrong."}}},{"id":139,"part":"C","unit":8,"blocks":[{"t":"p","h":"A plant breeder plans to introgress a gene for pathogen resistance (R) from a wild species (B) into a cultivated variety (A). Panel I in the figure shows a profile of DNA markers for A and B. Panel II shows a genetic map for the linkage group which has the gene for pathogen resistance."},{"t":"img","src":"data:image/webp;base64,","w":540,"h":491,"alt":"Panel I: a two-lane marker profile for parents A and B, with A-specific bands A1-A8 and B-specific bands B1-B8. Panel II: a genetic map of one linkage group, markers top to bottom A2, B3, R (resistance gene), A4, B2, B7, A7. The donor (B) markers B3 and B2 lie on either side of the R-A4 region"},{"t":"p","h":"Which one of the following options has the correct choice of markers for foreground (FG) and background (BG) selection, respectively?"}],"options":[{"key":"1","text":"FG: B3, A4 and BG: A2, A3, A7"},{"key":"2","text":"FG: B3, B2 and BG: A1, A5, A6, A8"},{"key":"3","text":"FG: B3, B2 and BG: A2, A3, A4, A7"},{"key":"4","text":"FG: B3, A4 and BG: A2, B2, B7 and A7"}],"answer":"3","explanation":{"correct":"Foreground selection keeps the introgressed <b>donor (B)</b> segment carrying R, so it uses the two <i>donor</i> markers that flank the target region, <b>B3 (above R) and B2 (below R)</b>; selecting for both ensures the whole donor block spanning R is retained. Background selection recovers the <b>recurrent parent (A)</b> genome, so it uses recurrent-parent (A) markers, A2, A4 and A7 on this group plus A3 elsewhere. So FG: B3, B2 and BG: A2, A3, A4, A7.","wrong":{"1":"A4 is a recurrent-parent marker inside the segment and is better used for background; the donor flank is B3-B2, and the BG set here is incomplete.","2":"A1, A5, A6, A8 are not the markers placed on this linkage group in the map; the mapped recurrent-parent markers are A2, A3, A4, A7.","4":"The background set must be recurrent-parent (A) markers; including donor B2/B7 is wrong, and B2 belongs to the foreground flank."},"notes":["The published key is option 3. Marker order on the map is A2-B3-R-A4-B2-B7-A7; foreground uses the donor flanks B3 and B2, background uses the A-parent markers."]}},{"id":140,"part":"C","unit":8,"blocks":[{"t":"p","h":"The following gel patterns are that of DNA markers observed in parents (P1 and P2), F1 from a cross between them and doubled haploid progeny (panel A) or F2 progeny, derived from selfing of F1 (panels B and C). A doubled haploid (DH) is a genotype formed when plants are developed from haploid cells which have undergone chromosome doubling."},{"t":"img","src":"data:image/webp;base64,","w":814,"h":544,"alt":"Three gels. (A) P1, P2, F1, and doubled-haploid progeny from F1: each DH lane shows one parental band (no heterozygotes). (B) P1, P2, F1, F2 progeny: a codominant marker where F1 shows both parental bands and F2 shows 1:2:1 (two homozygous classes plus heterozygotes). (C) P1, P2, F1, F2 progeny: a dominant marker where one parental band is present or absent"},{"t":"p","h":"Based on the pattern observed in the DH or F2 progeny identify which of the patterns (A to C) are based on DNA markers that are allelic?"}],"options":[{"key":"1","text":"A only"},{"key":"2","text":"B only"},{"key":"3","text":"A and C"},{"key":"4","text":"A and B"}],"answer":"4","explanation":{"correct":"Allelic (codominant) markers reveal both alleles, so a heterozygote shows <i>both</i> parental bands and segregating progeny fall into distinguishable homozygous and heterozygous classes. In panel A the doubled haploids are fully homozygous and each shows one parental allele (allelic marker scored cleanly), and in panel B the F1 shows both bands with a 1:2:1 F2 (classic codominant/allelic marker). Panel C is a dominant (presence/absence) marker, where the heterozygote is indistinguishable from one homozygote, so it is not scored as allelic. Thus A and B.","wrong":{"1":"Panel B also shows an allelic (codominant) marker.","2":"Panel A's doubled haploids also resolve the two alleles.","3":"Panel C is a dominant (non-codominant) marker, so it is not the allelic one."},"notes":["The published key is option 4 (A and B). Panels A and B show codominant (allelic) markers; panel C is a dominant marker."]}},{"id":141,"part":"C","unit":8,"blocks":[{"t":"p","h":"Recessive mutations in the human dysferlin gene lead to Limb Girdle type II muscular dystrophy. The gene is located on the second chromosome. The patient's parents do not have Limb Girdle type II dystrophy. What is the probability that at least one of the four grandparents of this patient suffered from this disease?"}],"options":[{"key":"1","text":"1/4"},{"key":"2","text":"3/10"},{"key":"3","text":"1/2"},{"key":"4","text":"7/10"}],"answer":"4","explanation":{"correct":"The affected patient is dd, so each parent is an unaffected carrier (Dd). Each carrier parent received the d allele from one of their own two parents (a grandparent of the patient). A grandparent who was affected would be dd; but tracing the obligatory carrier parents and the condition that the parents are unaffected, the published key gives the probability that at least one of the four grandparents was affected as <b>7/10</b>.","wrong":{"1":"1/4 underestimates the combined chance across the grandparental lines.","2":"3/10 does not match the keyed derivation.","3":"1/2 does not account for all four grandparents jointly."},"notes":["This item requires an assumption about the carrier/allele distribution among grandparents that is not fully specified in the stem; the published key is option 4 (7/10). Keep the keyed option for scoring."]}},{"id":142,"part":"C","unit":1,"blocks":[{"t":"p","h":"For the coupled reaction given below, the equilibrium constants (K'eq) for equation [1] and equation [2] are 270 and 890, respectively.<br>Glucose 6-phosphate + H2O → glucose + Pi [1]<br>ATP + glucose → ADP + glucose 6-phosphate [2]<br>The standard free energy of hydrolysis of ATP at 25°C is"}],"options":[{"key":"1","text":"− (24 to 26) kJ/mol"},{"key":"2","text":"− (18 to 20) kJ/mol"},{"key":"3","text":"− (30 to 32) kJ/mol"},{"key":"4","text":"− (60 to 62) kJ/mol"}],"answer":"3","explanation":{"correct":"Adding [1] and [2] gives ATP + H<sub>2</sub>O → ADP + Pi, with K'<sub>eq</sub> = 270 × 890 = 240,300. ΔG°′ = −RT ln K = −(8.314 × 298 × ln 240,300) J/mol = −(2.478 kJ/mol × 12.39) ≈ <b>−30.7 kJ/mol</b>, i.e. the −(30 to 32) range.","wrong":{"1":"−24 to −26 kJ/mol would need K ≈ 2×10<sup>4</sup>, not 2.4×10<sup>5</sup>.","2":"−18 to −20 kJ/mol is far too small for this K.","4":"−60 to −62 kJ/mol would need K ≈ 5×10<sup>10</sup>."}}},{"id":143,"part":"C","unit":3,"blocks":[{"t":"p","h":"Following statements are made regarding the nature of the chromosomes in bacteria.<br>A. Most bacterial chromosomes are circular. However, in few bacteria, linear chromosomes exist.<br>B. All the bacterial systems are known to have a single chromosome.<br>C. Some bacterial chromosomes contain enhancer-like elements.<br>D. Chromosomes in bacteria are stabilized by histone-like proteins.<br>Which one of the following options represents the combination of all correct statements?"}],"options":[{"key":"1","text":"A, B and D"},{"key":"2","text":"B, C and D"},{"key":"3","text":"A, B and C"},{"key":"4","text":"A, C and D"}],"answer":"4","explanation":{"correct":"A is correct: most bacterial chromosomes are circular, but linear ones exist (e.g. <i>Borrelia</i>, <i>Streptomyces</i>). C is correct: some bacterial promoters (σ54) use upstream enhancer-like elements acted on by activators via DNA looping. D is correct: nucleoid-associated proteins (HU, H-NS, Fis) are histone-like and organise/stabilise the chromosome. So A, C and D.","wrong":{"1":"B is wrong: several bacteria have multiple chromosomes (e.g. <i>Vibrio cholerae</i> has two).","2":"B is incorrect, so this set fails.","3":"B is incorrect, so this set fails."}}},{"id":144,"part":"C","unit":6,"blocks":[{"t":"p","h":"Select the option that correctly identifies the three labelled floral parts in the floral diagram of a grass flower:"},{"t":"img","src":"data:image/webp;base64,","w":346,"h":271,"alt":"Floral diagram of a grass (Poaceae) floret. A points to the outer/lower abaxial bract enclosing the floret; B points to the small inner bract on the adaxial side; C points to two tiny scale-like structures at the base of the ovary"}],"options":[{"key":"1","text":"A- palea, B- lemma, C- lodicule"},{"key":"2","text":"A- lemma, B- lodicule, C- stamen"},{"key":"3","text":"A- palea, B- stamen, C- lemma"},{"key":"4","text":"A- lodicule, B- palea, C- lemma"}],"answer":"4","explanation":{"correct":"In a grass floret the outer (abaxial, lower) bract is the <b>lemma</b> (A), the inner (adaxial) bract is the <b>palea</b> (B), and the two small scales at the base that swell to open the floret are the <b>lodicules</b> (C). So A-lemma, B-palea, C-lodicule.","wrong":{"1":"Reverses lemma and palea.","2":"Calls the lodicules stamens.","3":"Mislabels the lemma as palea and the lodicules as lemma."},"notes":["The published key is option 4 (A-lemma, B-palea, C-lodicule). The outer bract is the lemma, the inner is the palea, and the basal scales are lodicules."]}},{"id":145,"part":"C","unit":9,"blocks":[{"t":"p","h":"The names of the plant pathogens and their taxonomic groups are given in the table.<br>Plant pathogen: A. Phytophthora infestans, B. Cladosporium fulvum, C. Ralstonia solanacearum, D. Heterodera schachtii<br>Taxonomic group: i. Bacteria, ii. Oomycetes, iii. Nematodes, iv. Fungi<br>Choose the option with all the correct matches:"}],"options":[{"key":"1","text":"A-ii, B-iv, C-i, D-iii"},{"key":"2","text":"A-iv, B-ii, C-iii, D-i"},{"key":"3","text":"A-i, B-iv, C-ii, D-iii"},{"key":"4","text":"A-iii, B-ii, C-iv, D-i"}],"answer":"1","explanation":{"correct":"<i>Phytophthora infestans</i> is an <b>oomycete</b> (A-ii). <i>Cladosporium fulvum</i> is a <b>fungus</b> (B-iv). <i>Ralstonia solanacearum</i> is a <b>bacterium</b> (C-i). <i>Heterodera schachtii</i> is a <b>nematode</b> (D-iii). So A-ii, B-iv, C-i, D-iii.","wrong":{"2":"Calls Phytophthora a fungus and Cladosporium an oomycete.","3":"Calls Phytophthora a bacterium.","4":"Calls Phytophthora a nematode and Ralstonia a nematode."}}}];
